/* Family Star Jar — a full year of daily devotionals (366 days, incl. Feb 29).
 * Verse text: World English Bible (WEB), Public Domain.
 * Each day the board shows entry[dayOfYear-1]. Repeats yearly.
 * Fields: ref (reference), L (illuminated drop-cap), scripture, reflect, q, pray.
 */
window.DEVOS365=[
/* ===== JANUARY ===== */
{ref:"Genesis 1:1",L:"I",scripture:"“In the beginning, God created the heavens and the earth.”",reflect:"Before there was anything at all, there was God — and He made everything, including you.",q:"What is your favourite thing God made?",pray:"Thank You God for making our big, beautiful world and for making me."},
{ref:"Genesis 1:31",L:"G",scripture:"“God saw everything that he had made, and behold, it was very good.”",reflect:"When God finished making the world, He was happy with it. You are part of what He calls very good.",q:"Can you name three good things you can see right now?",pray:"Thank You God that Your world is good and that You made me good too."},
{ref:"Psalm 118:24",L:"T",scripture:"“This is the day that Yahweh has made. We will rejoice and be glad in it.”",reflect:"Every single morning is a gift from God — a brand new day to love Him and each other.",q:"What are you excited about today?",pray:"Thank You God for today. Help me be glad and kind all day long."},
{ref:"Proverbs 3:5",L:"T",scripture:"“Trust in Yahweh with all your heart, and don’t lean on your own understanding.”",reflect:"When things feel hard or scary, we can trust God — He is bigger and wiser than any worry.",q:"What is something you can trust God to help you with?",pray:"Help me trust You, God, even when I don’t understand. You always know best."},
{ref:"Ephesians 6:1",L:"C",scripture:"“Children, obey your parents in the Lord, for this is right.”",reflect:"Listening to Mummy and Daddy the first time, with a happy heart, makes God smile.",q:"How can you obey quickly and cheerfully today?",pray:"Jesus, help me listen well and obey with a joyful heart. Thank You for my family."},
{ref:"1 John 4:19",L:"W",scripture:"“We love him, because he first loved us.”",reflect:"We can love God and love others because God loved us first, more than we can imagine.",q:"Who can you show love to today?",pray:"Thank You for loving me first, God. Help my heart be full of love."},
{ref:"Psalm 23:1",L:"Y",scripture:"“Yahweh is my shepherd; I shall lack nothing.”",reflect:"A shepherd takes care of the sheep. God takes care of you and gives you what you need.",q:"How does God take care of your family?",pray:"Thank You for being my Shepherd, God. I feel safe with You."},
{ref:"Philippians 4:13",L:"I",scripture:"“I can do all things through Christ who strengthens me.”",reflect:"When something feels too hard, Jesus gives us the strength to keep trying.",q:"What is something hard you can try again, with Jesus helping you?",pray:"Jesus, please give me strength to do hard things and never give up."},
{ref:"Colossians 3:23",L:"W",scripture:"“Whatever you do, work heartily, as for the Lord.”",reflect:"Even tidying toys can be a gift to God when we do it with our whole heart.",q:"What job can you do so well it makes God smile?",pray:"Father, help me do my part with all my heart, as if I’m doing it for You."},
{ref:"Psalm 136:1",L:"G",scripture:"“Give thanks to Yahweh, for he is good, for his loving kindness endures forever.”",reflect:"God’s love never runs out and never stops — not ever. That is a wonderful reason to say thank You.",q:"What are you thankful for right now?",pray:"Thank You God that You are good and Your love lasts forever."},
{ref:"Ephesians 4:32",L:"B",scripture:"“Be kind to one another, tender hearted, forgiving each other.”",reflect:"Home is the best place to practise kindness — sharing, saying sorry, and forgiving fast.",q:"Who can you be kind to before bedtime?",pray:"Lord, give me a kind heart today. Help me forgive quickly, like You forgive me."},
{ref:"Joshua 1:9",L:"B",scripture:"“Be strong and courageous. Don’t be afraid… for Yahweh your God is with you.”",reflect:"We can be brave because we are never alone — God goes with us everywhere.",q:"When do you need to be brave?",pray:"Help me be brave, God. Thank You that You are always with me."},
{ref:"Matthew 5:16",L:"L",scripture:"“Let your light shine before men, that they may see your good works.”",reflect:"When we are kind and good, it’s like a little light that helps others see God’s love.",q:"How can your light shine for someone today?",pray:"Help my light shine, Jesus, so others can see Your love in me."},
{ref:"Psalm 139:14",L:"I",scripture:"“I will give thanks to you, for I am fearfully and wonderfully made.”",reflect:"God made you on purpose, with great care. There is no one else exactly like you.",q:"What is something special about the way God made you?",pray:"Thank You God for making me wonderfully. I’m glad to be me."},
{ref:"1 Thessalonians 5:18",L:"G",scripture:"“In everything give thanks, for this is God’s will for you in Christ Jesus.”",reflect:"A thankful heart notices God’s gifts everywhere — food, family, sunshine, and second chances.",q:"Name three things you’re thankful for today.",pray:"Thank You Jesus for all Your good gifts. Help our family have thankful hearts."},
{ref:"Proverbs 17:17",L:"A",scripture:"“A friend loves at all times.”",reflect:"Brothers and sisters can be our very best friends — sticking together on good days and hard days.",q:"How can you be a good friend to someone this week?",pray:"Lord, make our family close friends who love each other well."},
{ref:"Matthew 19:14",L:"L",scripture:"“Allow the little children… to come to me; for the Kingdom of Heaven belongs to such.”",reflect:"Jesus loves children very much. He always wants you close to Him.",q:"What would you like to tell Jesus today?",pray:"Thank You Jesus that You love children like me. I want to be close to You."},
{ref:"Psalm 56:3",L:"W",scripture:"“When I am afraid, I will put my trust in you.”",reflect:"Everyone feels scared sometimes. When we do, we can whisper to God and He helps us feel calm.",q:"What helps you feel brave when you’re scared?",pray:"When I’m afraid, God, help me remember You are near. I trust You."},
{ref:"1 John 4:7",L:"B",scripture:"“Beloved, let’s love one another, for love is of God.”",reflect:"Love flows from God into us, and out to each other. A loving family is a little picture of God’s love.",q:"How were you loved today, and how can you pass it on?",pray:"Thank You God that Your love fills our home. Help our family love like You."},
{ref:"Exodus 20:12",L:"H",scripture:"“Honour your father and your mother.”",reflect:"Honouring means treating someone as precious — with kind words, respect, and trust.",q:"What kind words can you say to your family right now?",pray:"God, thank You for Mummy and Daddy. Help me honour them with my words and choices."},
{ref:"Psalm 34:8",L:"O",scripture:"“Oh taste and see that Yahweh is good.”",reflect:"The more we get to know God, the more we see how good and kind He really is.",q:"What is one good thing God has done for you?",pray:"Help me see how good You are, God, in the big and little things."},
{ref:"Matthew 6:26",L:"L",scripture:"“See the birds… your heavenly Father feeds them. Aren’t you of much more value?”",reflect:"God feeds the little birds, and He cares for you even more. You never have to worry.",q:"How does God take care of the animals? And you?",pray:"Thank You Father that You care for me even more than the birds. I won’t worry."},
{ref:"Galatians 5:22",L:"T",scripture:"“The fruit of the Spirit is love, joy, peace, patience, kindness…”",reflect:"When God’s Spirit lives in us, good things grow in our hearts, like fruit on a tree.",q:"Which one of these can you grow today — love, joy, or kindness?",pray:"Holy Spirit, grow good fruit in my heart so I can bless my family."},
{ref:"Psalm 100:1",L:"M",scripture:"“Make a joyful shout to Yahweh, all you lands!”",reflect:"We can praise God with happy voices, songs, and dancing. He loves to hear us celebrate Him.",q:"What is your favourite song to sing to God?",pray:"I want to praise You with a happy heart today, God. You are wonderful!"},
{ref:"Proverbs 15:1",L:"A",scripture:"“A gentle answer turns away wrath, but a harsh word stirs up anger.”",reflect:"Soft, kind words help calm arguments. Gentle words are strong and wise.",q:"How can you use gentle words when you feel upset?",pray:"Help me speak gently, God, even when I feel cross. Kind words are best."},
{ref:"John 13:34",L:"A",scripture:"“A new commandment I give to you, that you love one another.”",reflect:"Jesus asked us to love each other the way He loves us — patiently and kindly.",q:"How did Jesus show love to people?",pray:"Jesus, teach me to love others the same way You love me."},
{ref:"Psalm 46:1",L:"G",scripture:"“God is our refuge and strength, a very present help in trouble.”",reflect:"A refuge is a safe place. Whenever we need help, God is right there with us.",q:"Where do you feel safe? God is even safer than that.",pray:"Thank You God for being my safe place whenever I need help."},
{ref:"Luke 6:31",L:"D",scripture:"“As you would like people to do to you, do exactly so to them.”",reflect:"Treat others the way you’d like to be treated — with sharing, kindness, and gentle hands.",q:"How do you like to be treated by others?",pray:"Help me treat others kindly, God, just how I’d love to be treated."},
{ref:"Psalm 121:2",L:"M",scripture:"“My help comes from Yahweh, who made heaven and earth.”",reflect:"The One who made the whole sky and earth is the same One who helps you. That’s amazing!",q:"Who do you go to when you need help?",pray:"Thank You God that my help comes from You, the Maker of everything."},
{ref:"Proverbs 16:24",L:"P",scripture:"“Pleasant words are… sweet to the soul, and health to the bones.”",reflect:"Kind words are like honey — they make people feel warm and happy inside.",q:"What kind words can you give someone today?",pray:"Help my words be sweet and kind, God, so they cheer people up."},
{ref:"Isaiah 41:10",L:"D",scripture:"“Don’t be afraid, for I am with you… I will strengthen you… I will help you.”",reflect:"God gives us three big promises here: He is with us, He makes us strong, and He helps us.",q:"Which promise do you need to remember today?",pray:"Thank You God that You are with me, You strengthen me, and You help me."},
/* ===== FEBRUARY ===== */
{ref:"1 Corinthians 13:4",L:"L",scripture:"“Love is patient and is kind. Love doesn’t envy.”",reflect:"Real love waits patiently and stays kind — even when it’s hard. That’s how God loves us.",q:"How can you be patient and kind today?",pray:"Help me love with patience and kindness, God, just like You do."},
{ref:"1 Corinthians 13:5",L:"L",scripture:"“Love… is not easily provoked, takes no account of evil.”",reflect:"Love doesn’t keep a list of when others were unkind. It forgives and lets go.",q:"Is there something you can forgive and let go of today?",pray:"Help me not stay cross, God, but forgive like You forgive me."},
{ref:"Psalm 51:10",L:"C",scripture:"“Create in me a clean heart, O God.”",reflect:"When we do wrong, we can ask God to make our hearts clean again. He always says yes.",q:"What can you ask God to help your heart do better?",pray:"Make my heart clean, God, and help me choose good things."},
{ref:"John 15:12",L:"L",scripture:"“This is my commandment, that you love one another, even as I have loved you.”",reflect:"Jesus loves us so much He gave everything. He asks us to love each other that way too.",q:"How much does Jesus love you? Even more than that!",pray:"Jesus, fill me with Your love so I can love my family well."},
{ref:"Psalm 27:1",L:"Y",scripture:"“Yahweh is my light and my salvation. Whom shall I fear?”",reflect:"With God as our light, the dark and the scary things don’t have to frighten us.",q:"What makes you feel brave?",pray:"You are my light, God. With You, I don’t need to be afraid."},
{ref:"Romans 12:10",L:"B",scripture:"“In love of the brothers be tenderly affectionate to one another.”",reflect:"Being tender means being gentle and warm with our family — soft hands and kind words.",q:"How can you be gentle with your brother or sister today?",pray:"Help me be tender and warm with my family, God."},
{ref:"Proverbs 22:6",L:"T",scripture:"“Train up a child in the way he should go, and… he will not depart from it.”",reflect:"When we learn to love God while we’re little, that love stays in our hearts as we grow.",q:"What is one good thing you are learning about God?",pray:"Thank You God for helping me learn to love and follow You."},
{ref:"Psalm 119:105",L:"Y",scripture:"“Your word is a lamp to my feet, and a light for my path.”",reflect:"The Bible is like a torch that shows us the right way to go.",q:"What is your favourite Bible story?",pray:"Thank You for the Bible, God. Let it light up my way."},
{ref:"Matthew 22:39",L:"Y",scripture:"“You shall love your neighbour as yourself.”",reflect:"A neighbour is anyone near us. God asks us to care for them as much as we care for ourselves.",q:"Who is a neighbour you can be kind to?",pray:"Help me love the people around me, God, with a caring heart."},
{ref:"Psalm 37:5",L:"C",scripture:"“Commit your way to Yahweh. Trust in him, and he will do it.”",reflect:"When we give God our plans and worries, He helps everything work out in the best way.",q:"What can you hand over to God today?",pray:"I give You my day, God. I trust You to take care of it."},
{ref:"Colossians 3:12",L:"P",scripture:"“Put on… a heart of compassion, kindness, lowliness, humility, and perseverance.”",reflect:"Each morning we can ‘put on’ kindness like a cosy jumper, ready to warm others.",q:"Which kind thing will you ‘put on’ today?",pray:"Help me wear kindness and gentleness everywhere I go, God."},
{ref:"Psalm 145:9",L:"Y",scripture:"“Yahweh is good to all. His tender mercies are over all his works.”",reflect:"God is good to everyone and everything He made. His kindness has no end.",q:"How has God been good to you today?",pray:"Thank You God for being good to me and to everyone."},
{ref:"John 14:27",L:"P",scripture:"“Peace I leave with you. My peace I give to you.”",reflect:"Jesus gives us a calm, peaceful feeling inside, even when things are noisy or hard.",q:"What helps you feel calm and peaceful?",pray:"Thank You Jesus for Your peace. Help my heart feel calm today."},
{ref:"1 John 4:16",L:"G",scripture:"“God is love, and he who remains in love remains in God.”",reflect:"God isn’t just loving — He IS love. When we love, we stay close to Him.",q:"How can you stay close to God today?",pray:"Fill me with Your love, God, so I stay close to You all day."},
{ref:"Psalm 90:2",L:"B",scripture:"“Even from everlasting to everlasting, you are God.”",reflect:"God has always been, and always will be. He never began and will never end.",q:"Isn’t it amazing that God has no beginning or end?",pray:"Thank You God that You are forever and always the same."},
{ref:"Proverbs 18:24",L:"T",scripture:"“There is a friend who sticks closer than a brother.”",reflect:"Jesus is the best friend of all — He never leaves and always loves.",q:"What makes someone a good friend?",pray:"Thank You Jesus for being my closest, truest friend."},
{ref:"Matthew 5:9",L:"B",scripture:"“Blessed are the peacemakers, for they shall be called children of God.”",reflect:"A peacemaker helps stop fights and brings friends back together. God loves peacemakers.",q:"How can you help make peace when others argue?",pray:"Help me be a peacemaker, God, who brings calm and kindness."},
{ref:"Psalm 103:13",L:"L",scripture:"“Like a father has compassion on his children, so Yahweh has compassion on those who fear him.”",reflect:"God cares for us with the tender love of the very best Father.",q:"How does a good dad care for his children?",pray:"Thank You God for loving me like the very best Father."},
{ref:"Philippians 2:4",L:"E",scripture:"“Each of you not just looking to his own things, but… to the things of others.”",reflect:"Thinking about what others need — not just ourselves — is a beautiful way to love.",q:"Whose needs can you think about today?",pray:"Help me notice what others need, God, and help however I can."},
{ref:"Psalm 62:8",L:"T",scripture:"“Trust in him at all times… pour out your heart before him.”",reflect:"We can tell God everything — our happy things and our sad things. He always listens.",q:"What would you like to tell God right now?",pray:"I pour out my heart to You, God. Thank You for always listening."},
{ref:"Galatians 6:9",L:"L",scripture:"“Let’s not be weary in doing good, for we will reap… if we don’t give up.”",reflect:"Doing good again and again can be tiring, but good seeds always grow in the end.",q:"What good thing can you keep doing, even when it’s hard?",pray:"Help me keep doing good, God, and never give up."},
{ref:"Psalm 8:1",L:"Y",scripture:"“Yahweh, our Lord, how majestic is your name in all the earth!”",reflect:"God’s name is great and wonderful everywhere — in the mountains, the sea, and the stars.",q:"Where do you see how great God is?",pray:"Your name is wonderful, God! I see how great You are everywhere."},
{ref:"Ephesians 4:2",L:"W",scripture:"“With… lowliness and humility, with patience, bearing with one another in love.”",reflect:"Being patient with each other, even when we’re annoyed, is how love holds a family together.",q:"Who can you be patient with today?",pray:"Help me be patient and gentle with my family, God."},
{ref:"Psalm 30:5",L:"W",scripture:"“Weeping may stay for the night, but joy comes in the morning.”",reflect:"Sad feelings don’t last forever. God brings happy mornings after hard nights.",q:"What makes a sad day feel better?",pray:"Thank You God that You bring joy again. Sad times don’t last forever."},
{ref:"Mark 12:30",L:"Y",scripture:"“You shall love the Lord your God with all your heart… and with all your strength.”",reflect:"We can love God with everything we have — our thoughts, our feelings, and our energy.",q:"How can you show God you love Him with all your heart?",pray:"I love You with all my heart, God. Help me love You more and more."},
{ref:"Proverbs 11:25",L:"A",scripture:"“He who waters shall be watered also himself.”",reflect:"When we bless others, God has a wonderful way of blessing us too.",q:"Who can you ‘water’ with kindness today?",pray:"Help me bless others, God, with a generous, cheerful heart."},
{ref:"Psalm 143:8",L:"L",scripture:"“Let me hear your loving kindness in the morning, for I trust in you.”",reflect:"Every morning we can listen for God’s love, ready to guide us through the day.",q:"What is a good way to start the morning with God?",pray:"Each morning, God, remind me of Your love and lead my day."},
{ref:"John 8:12",L:"I",scripture:"“I am the light of the world. He who follows me will… have the light of life.”",reflect:"Jesus is like a bright light who shows us the way and chases the darkness away.",q:"How does a light help you when it’s dark?",pray:"Jesus, be my light. Help me follow You wherever You lead."},
{ref:"Psalm 116:1",L:"I",scripture:"“I love Yahweh, because he listens to my voice and my cries for mercy.”",reflect:"God always hears us when we call — even our smallest whisper. That’s a reason to love Him.",q:"How does it feel to be truly listened to?",pray:"I love You God, because You always hear me when I call."},
/* ===== MARCH ===== */
{ref:"Psalm 19:1",L:"T",scripture:"“The heavens declare the glory of God. The expanse shows his handiwork.”",reflect:"The sky, the stars, and the clouds are like a picture God painted to show how great He is.",q:"What do you see in the sky that God made?",pray:"Thank You God for the beautiful sky that shows how wonderful You are."},
{ref:"Matthew 7:12",L:"D",scripture:"“Whatever you desire for men to do to you, you shall also do to them.”",reflect:"This is the golden rule: treat others just how you would love to be treated.",q:"How would you like a friend to treat you today?",pray:"Help me follow Your golden rule, God, and treat others kindly."},
{ref:"Psalm 28:7",L:"Y",scripture:"“Yahweh is my strength and my shield. My heart has trusted in him, and I am helped.”",reflect:"God is strong like a shield that keeps us safe. We can always trust Him to help.",q:"What does a shield do? God protects you like that.",pray:"Thank You God for being my strength and my shield. I trust You."},
{ref:"1 Peter 5:7",L:"C",scripture:"“Cast all your worries on him, because he cares for you.”",reflect:"When worries feel heavy, we can hand them to God like a backpack. He gladly carries them.",q:"Is there a worry you can give to God today?",pray:"Here are my worries, God. Thank You for caring and carrying them for me."},
{ref:"Proverbs 12:25",L:"A",scripture:"“Anxiety in a man’s heart weighs it down, but a kind word makes it glad.”",reflect:"One kind word can turn a heavy, sad heart into a happy one. Words are powerful!",q:"Whose day can you make glad with a kind word?",pray:"Help me speak words that make hearts glad, God."},
{ref:"Psalm 33:5",L:"T",scripture:"“The earth is full of the loving kindness of Yahweh.”",reflect:"God’s kindness fills the whole earth — you can find it everywhere if you look.",q:"Where did you see God’s kindness today?",pray:"Thank You God that Your kindness fills the whole earth."},
{ref:"John 3:16",L:"F",scripture:"“For God so loved the world, that he gave his one and only Son.”",reflect:"God loved us so much He sent Jesus. That is the biggest love story ever told.",q:"How big is God’s love for you?",pray:"Thank You God for loving me so much that You gave us Jesus."},
{ref:"Psalm 63:7",L:"B",scripture:"“For you have been my help. I will rejoice in the shadow of your wings.”",reflect:"Like a mother bird covers her chicks, God covers us with safety and love.",q:"Where do you feel safe and cosy?",pray:"Thank You God for keeping me safe under Your wings."},
{ref:"Romans 15:7",L:"A",scripture:"“Accept one another, even as Christ also accepted you.”",reflect:"Jesus welcomes everyone. We can welcome others too, so no one feels left out.",q:"Who can you make feel welcome today?",pray:"Help me welcome others warmly, God, the way Jesus welcomes me."},
{ref:"Psalm 91:11",L:"H",scripture:"“He will put his angels in charge of you, to guard you in all your ways.”",reflect:"God cares so much that He sends help to watch over us wherever we go.",q:"How does it feel to know God is watching over you?",pray:"Thank You God for watching over me everywhere I go."},
{ref:"Ephesians 2:10",L:"W",scripture:"“We are his workmanship, created… for good works.”",reflect:"You are God’s handmade treasure, made to do good and kind things.",q:"What good work can you do today?",pray:"Thank You for making me, God. Help me do the good things You planned."},
{ref:"Psalm 118:1",L:"G",scripture:"“Give thanks to Yahweh, for he is good, for his loving kindness endures forever.”",reflect:"Saying thank You to God is a happy habit we can do every single day.",q:"What are three thank-yous you can give God right now?",pray:"Thank You God for being so good to me and my family."},
{ref:"Matthew 6:14",L:"F",scripture:"“For if you forgive men their trespasses, your heavenly Father will also forgive you.”",reflect:"Forgiving means letting go of an ‘ouch’ someone gave us. God helps us forgive.",q:"Is there someone you can forgive today?",pray:"Help me forgive others, God, the way You forgive me."},
{ref:"Psalm 139:7",L:"W",scripture:"“Where could I go from your Spirit? Or where could I flee from your presence?”",reflect:"There is nowhere we could ever go where God is not with us. He is always near.",q:"Where have you been today? God was with you the whole time!",pray:"Thank You God that You are always with me, wherever I go."},
{ref:"1 John 3:18",L:"L",scripture:"“Let’s not love in word only… but in deed and truth.”",reflect:"Love isn’t just saying nice things — it’s doing kind things too.",q:"What kind action can show your love today?",pray:"Help me show love by what I do, God, not just what I say."},
{ref:"Psalm 96:1",L:"S",scripture:"“Sing to Yahweh a new song! Sing to Yahweh, all the earth.”",reflect:"We can make up new songs to God any time. He loves to hear our joyful voices.",q:"Can you make up a little song for God right now?",pray:"I want to sing to You, God, with a happy new song today."},
{ref:"Proverbs 3:9",L:"H",scripture:"“Honour Yahweh with your substance… and with the first fruits of all your increase.”",reflect:"We can give our best to God first — our time, our toys to share, and our thank-yous.",q:"What is one good thing you can give to God first?",pray:"Help me give my best to You first, God, with a happy heart."},
{ref:"Psalm 34:18",L:"Y",scripture:"“Yahweh is near to those who have a broken heart.”",reflect:"When we feel sad or hurt, God comes especially close to comfort us.",q:"What makes you feel better when you’re sad?",pray:"Thank You God for coming close when my heart feels sad."},
{ref:"Colossians 3:20",L:"C",scripture:"“Children, obey your parents in all things, for this pleases the Lord.”",reflect:"When we obey with a happy heart, it makes both our parents and God glad.",q:"How can you obey happily today?",pray:"Help me obey with a cheerful heart, God, in all things."},
{ref:"Psalm 25:4",L:"S",scripture:"“Show me your ways, Yahweh. Teach me your paths.”",reflect:"We can ask God to show us the right way to go, and He gladly teaches us.",q:"What do you want to ask God to teach you?",pray:"Show me Your ways, God, and teach me to walk with You."},
{ref:"Luke 6:36",L:"B",scripture:"“Therefore be merciful, even as your Father is also merciful.”",reflect:"Being merciful means being gentle and giving second chances, just like God does for us.",q:"Who can you give a second chance today?",pray:"Help me be merciful and gentle, God, like You are with me."},
{ref:"Psalm 147:3",L:"H",scripture:"“He heals the broken in heart, and binds up their wounds.”",reflect:"God is like a gentle doctor for our hearts, making sad and hurt feelings better.",q:"How does God take care of your feelings?",pray:"Thank You God for healing my heart when it hurts."},
{ref:"James 1:19",L:"L",scripture:"“Let every man be swift to hear, slow to speak, and slow to anger.”",reflect:"Good listening means big ears, a quiet mouth, and a patient heart.",q:"How can you be a great listener today?",pray:"Help me listen well, speak kindly, and stay calm, God."},
{ref:"Psalm 100:5",L:"F",scripture:"“For Yahweh is good. His loving kindness endures forever.”",reflect:"God’s goodness never runs out — it lasts and lasts, forever and ever.",q:"What is a good thing that makes you happy about God?",pray:"Thank You God that You are good, forever and always."},
{ref:"Matthew 11:28",L:"C",scripture:"“Come to me, all you who labour… and I will give you rest.”",reflect:"When we feel tired or worn out, Jesus invites us to rest with Him and feel calm.",q:"What makes you feel tired? Jesus gives you rest.",pray:"Thank You Jesus for giving me rest when I feel tired."},
{ref:"Psalm 133:1",L:"H",scripture:"“How good and how pleasant it is for brothers to live together in unity!”",reflect:"When a family gets along and helps each other, it makes God and everyone happy.",q:"How can you help your family get along today?",pray:"Help our family live together in peace and love, God."},
{ref:"Proverbs 16:3",L:"C",scripture:"“Commit your deeds to Yahweh, and your plans shall succeed.”",reflect:"When we ask God to help our plans, He guides us to what is best.",q:"What plan can you ask God to help with today?",pray:"I give my plans to You, God. Please guide me in the best way."},
{ref:"Psalm 145:18",L:"Y",scripture:"“Yahweh is near to all those who call on him… in truth.”",reflect:"Whenever we call on God with an honest heart, He is right there, close to us.",q:"What would you like to call out to God about?",pray:"Thank You God for being near whenever I call on You."},
{ref:"John 15:5",L:"I",scripture:"“I am the vine. You are the branches.”",reflect:"Just like branches stay joined to a tree, we stay joined to Jesus, and He helps us grow.",q:"How does a branch get strong? By staying on the tree!",pray:"Help me stay close to You, Jesus, so I can grow good and strong."},
{ref:"Psalm 5:3",L:"Y",scripture:"“Yahweh, in the morning you will hear my voice.”",reflect:"Talking to God first thing in the morning is a lovely way to start the day.",q:"What will you say to God this morning?",pray:"Good morning, God! Thank You for hearing me at the start of my day."},
{ref:"Zephaniah 3:17",L:"Y",scripture:"“Yahweh your God is among you… he will rejoice over you with joy.”",reflect:"God is so happy about you that He rejoices over you with singing and delight!",q:"How does it feel that God delights in you?",pray:"Thank You God that You delight in me and rejoice over me with joy."},
/* ===== APRIL ===== */
{ref:"John 11:25",L:"I",scripture:"“I am the resurrection and the life. He who believes in me will still live.”",reflect:"Jesus is stronger than anything sad — even death. Because of Him, we can have hope forever.",q:"What does it mean that Jesus gives us life?",pray:"Thank You Jesus that You give life and hope that never ends."},
{ref:"Luke 24:6",L:"H",scripture:"“He isn’t here, but is risen!”",reflect:"Jesus came alive again after Easter! It is the happiest, most amazing surprise in the world.",q:"Why is it wonderful that Jesus is alive?",pray:"Thank You Jesus that You are alive! You beat sadness and death."},
{ref:"Psalm 118:14",L:"Y",scripture:"“Yah is my strength and song. He has become my salvation.”",reflect:"God gives us strength and puts a happy song in our hearts.",q:"What song is in your heart today?",pray:"Thank You God for being my strength and my song."},
{ref:"Romans 5:8",L:"G",scripture:"“God commends his own love toward us, in that… Christ died for us.”",reflect:"Jesus loved us even before we loved Him. His love came first and never stops.",q:"How did Jesus show the biggest love?",pray:"Thank You Jesus for loving me so much, even before I knew You."},
{ref:"Psalm 16:11",L:"Y",scripture:"“In your presence is fullness of joy.”",reflect:"Being close to God fills us up with the very best kind of happiness.",q:"What fills you with joy?",pray:"Thank You God that being near You makes my heart full of joy."},
{ref:"Matthew 28:20",L:"I",scripture:"“Behold, I am with you always, even to the end of the age.”",reflect:"Jesus promised to be with us always — not just some days, but every day forever.",q:"How does it help to know Jesus is always with you?",pray:"Thank You Jesus for being with me always. I’m never alone."},
{ref:"Psalm 145:8",L:"Y",scripture:"“Yahweh is gracious, merciful, slow to anger, and of great loving kindness.”",reflect:"God is patient and full of kindness. He is never grumpy or in a rush to be cross.",q:"How can you be patient like God today?",pray:"Thank You God for being patient and kind. Help me be that way too."},
{ref:"Proverbs 4:23",L:"K",scripture:"“Keep your heart with all diligence, for out of it is the wellspring of life.”",reflect:"Our hearts are like a spring of water — we look after them by filling them with good things.",q:"What good things can you put in your heart today?",pray:"Help me guard my heart, God, and fill it with good and true things."},
{ref:"Psalm 42:1",L:"A",scripture:"“As the deer pants for the water brooks, so my soul pants after you, God.”",reflect:"Just as a thirsty deer wants water, our hearts really want to be close to God.",q:"What are you thirsty for? Our hearts are thirsty for God.",pray:"I want to be close to You, God. You are what my heart needs."},
{ref:"1 Corinthians 16:14",L:"L",scripture:"“Let all that you do be done in love.”",reflect:"Everything — playing, sharing, helping — can be done with love in our hearts.",q:"How can you add love to what you do today?",pray:"Help me do everything with love, God, in big and little things."},
{ref:"Psalm 46:10",L:"B",scripture:"“Be still, and know that I am God.”",reflect:"Sometimes the best thing is to be quiet and calm and remember how great God is.",q:"Can you sit very still and think about God for a moment?",pray:"Help me be still and calm, God, and remember how great You are."},
{ref:"Matthew 5:7",L:"B",scripture:"“Blessed are the merciful, for they shall obtain mercy.”",reflect:"When we are gentle and forgiving to others, God is gentle and forgiving to us.",q:"How can you show mercy to someone today?",pray:"Help me be merciful, God, giving kindness and second chances."},
{ref:"Psalm 121:8",L:"Y",scripture:"“Yahweh will keep your going out and your coming in.”",reflect:"When we leave home and when we come back, God is watching over every step.",q:"Where will you go today? God goes with you.",pray:"Thank You God for keeping me safe when I go out and come home."},
{ref:"Galatians 5:13",L:"T",scripture:"“Through love, be servants to one another.”",reflect:"Serving means helping others because we love them. Even little helpers make God smile.",q:"How can you serve someone in your family today?",pray:"Help me serve my family with love, God, like a joyful helper."},
{ref:"Psalm 32:8",L:"I",scripture:"“I will instruct you and teach you in the way which you shall go.”",reflect:"God promises to guide us and show us the way, like a loving teacher.",q:"What do you want God to guide you in?",pray:"Thank You God for teaching me and showing me the right way."},
{ref:"1 John 5:14",L:"T",scripture:"“This is the boldness which we have toward him, that… he listens to us.”",reflect:"We can talk to God about anything, sure that He is listening carefully.",q:"What do you want to talk to God about today?",pray:"Thank You God that I can come to You and You always listen."},
{ref:"Psalm 92:1",L:"I",scripture:"“It is a good thing to give thanks to Yahweh.”",reflect:"Saying thank You to God is always a good idea, and it fills our hearts with joy.",q:"What thank-you can you give God right now?",pray:"Thank You God! It’s so good to say thank You to You."},
{ref:"Proverbs 15:13",L:"A",scripture:"“A glad heart makes a cheerful face.”",reflect:"When our hearts are happy in God, it shows on our faces with big smiles.",q:"Can you show a big happy smile right now?",pray:"Fill my heart with gladness, God, so my smile shines bright."},
{ref:"Psalm 55:22",L:"C",scripture:"“Cast your burden on Yahweh and he will sustain you.”",reflect:"A burden is something heavy. God is happy to carry our heavy feelings for us.",q:"What heavy feeling can you give to God today?",pray:"I give my heavy feelings to You, God. Thank You for carrying them."},
{ref:"John 14:6",L:"I",scripture:"“I am the way, the truth, and the life.”",reflect:"Jesus shows us the way to God — He is the path, the truth, and true life.",q:"Where does following Jesus lead us?",pray:"Thank You Jesus for being the way to God. I want to follow You."},
{ref:"Psalm 34:1",L:"I",scripture:"“I will bless Yahweh at all times. His praise will always be in my mouth.”",reflect:"We can praise God all the time — on happy days and even on tricky days.",q:"What can you praise God for today?",pray:"I will praise You at all times, God. You are always good."},
{ref:"Romans 8:28",L:"W",scripture:"“All things work together for good for those who love God.”",reflect:"Even when things go wrong, God can turn them into something good. He is that clever and kind.",q:"Can you think of a time something turned out okay in the end?",pray:"Thank You God that You work everything together for good."},
{ref:"Psalm 71:5",L:"F",scripture:"“For you are my hope, Lord Yahweh, my confidence from my youth.”",reflect:"God is our hope even when we are little. We can trust Him our whole lives.",q:"What do you hope for? God is our biggest hope.",pray:"You are my hope, God. I will trust You all my life."},
{ref:"Proverbs 19:17",L:"H",scripture:"“He who has pity on the poor lends to Yahweh.”",reflect:"When we help someone in need, it’s like we are giving a gift straight to God.",q:"Who is someone you could help who needs it?",pray:"Help me care for people in need, God, with a giving heart."},
{ref:"Psalm 86:5",L:"F",scripture:"“For you, Lord, are good, and ready to forgive.”",reflect:"God is always ready to forgive when we say sorry. He loves to give fresh starts.",q:"Isn’t it wonderful that God is quick to forgive?",pray:"Thank You God that You are good and always ready to forgive me."},
{ref:"Matthew 18:20",L:"F",scripture:"“Where two or three are gathered together in my name, there I am among them.”",reflect:"When our family prays together, Jesus is right there with us.",q:"How does it feel to pray together as a family?",pray:"Thank You Jesus for being with us when we gather to pray."},
{ref:"Psalm 143:10",L:"T",scripture:"“Teach me to do your will, for you are my God.”",reflect:"We can ask God to help us do what is right and good.",q:"What good thing can you ask God to help you do?",pray:"Teach me to do what pleases You, God. I want to follow Your way."},
{ref:"1 Peter 4:8",L:"A",scripture:"“Above all things be earnest in your love among yourselves.”",reflect:"Loving each other is the most important thing of all — even more than being right.",q:"How can you make love your most important thing today?",pray:"Help me love others deeply, God, above everything else."},
{ref:"Psalm 37:4",L:"D",scripture:"“Also delight yourself in Yahweh, and he will give you the desires of your heart.”",reflect:"When we find our happiness in God, He fills our hearts with good things.",q:"What makes you happy about God?",pray:"I delight in You, God. Thank You for the good things You give."},
{ref:"John 16:33",L:"I",scripture:"“In me you may have peace… I have overcome the world.”",reflect:"With Jesus, we can feel peaceful even when things are hard, because He is stronger than everything.",q:"What helps you feel peaceful?",pray:"Thank You Jesus for Your peace. You are stronger than anything hard."},
/* ===== MAY ===== */
{ref:"Psalm 150:6",L:"L",scripture:"“Let everything that has breath praise Yah!”",reflect:"Every living thing can praise God — birds, animals, and you with your happy voice!",q:"How can you praise God right now?",pray:"With every breath, God, I want to praise You today!"},
{ref:"Proverbs 3:6",L:"I",scripture:"“In all your ways acknowledge him, and he will make your paths straight.”",reflect:"When we remember God in everything we do, He helps us find the right way.",q:"How can you remember God in what you do today?",pray:"Help me remember You in all I do, God, and lead me the right way."},
{ref:"Psalm 31:24",L:"B",scripture:"“Be strong, and let your heart take courage, all you who hope in Yahweh.”",reflect:"Hope in God gives our hearts courage, like a warm brave feeling inside.",q:"What makes your heart feel brave?",pray:"Fill my heart with courage, God, as I put my hope in You."},
{ref:"1 John 3:1",L:"S",scripture:"“See how great a love the Father has given to us, that we should be called children of God!”",reflect:"God calls us His children! We belong to Him and He loves us dearly.",q:"How does it feel to be a child of God?",pray:"Thank You God for calling me Your child. I’m so glad I belong to You."},
{ref:"Psalm 103:2",L:"P",scripture:"“Praise Yahweh, my soul, and don’t forget all his benefits.”",reflect:"It’s good to remember all the kind things God does and to thank Him for each one.",q:"What good things has God done that you can remember?",pray:"Help me never forget Your kindness, God. Thank You for everything."},
{ref:"Colossians 3:13",L:"B",scripture:"“Bearing with one another, and forgiving each other.”",reflect:"Being patient and forgiving with each other keeps our family close and happy.",q:"Who can you be patient with today?",pray:"Help me be patient and forgiving, God, just like You are with me."},
{ref:"Psalm 84:11",L:"F",scripture:"“For Yahweh God is a sun and a shield. Yahweh will give grace and glory.”",reflect:"God is like warm sunshine and a strong shield — He gives us light and keeps us safe.",q:"How is God like the sun? How is He like a shield?",pray:"Thank You God for being my warm sun and my safe shield."},
{ref:"Matthew 5:14",L:"Y",scripture:"“You are the light of the world. A city… can’t be hidden.”",reflect:"Your kindness is a light that others can see, brightening the world around you.",q:"How can your light shine bright today?",pray:"Help my light shine, Jesus, so others feel Your love and warmth."},
{ref:"Psalm 100:2",L:"S",scripture:"“Serve Yahweh with gladness. Come before his presence with singing.”",reflect:"We can serve and worship God with joyful, happy hearts.",q:"What makes you glad to worship God?",pray:"I want to serve You with gladness, God, and sing to You today."},
{ref:"Proverbs 10:12",L:"L",scripture:"“Love covers all wrongs.”",reflect:"Love is so strong it can cover over the times people are unkind, with forgiveness.",q:"How can love help when someone is unkind?",pray:"Help my love be strong, God, covering wrongs with forgiveness."},
{ref:"Psalm 18:1",L:"I",scripture:"“I love you, Yahweh, my strength.”",reflect:"We can tell God simply and honestly, ‘I love You!’ It makes Him glad.",q:"Can you tell God you love Him right now?",pray:"I love You, God! You are my strength and I’m so thankful for You."},
{ref:"Isaiah 40:31",L:"T",scripture:"“Those who wait for Yahweh will renew their strength… they will run and not be weary.”",reflect:"When we trust God and wait for Him, He gives us fresh strength, like wings to soar.",q:"What can you trust God to help you with?",pray:"Thank You God for giving me new strength when I trust in You."},
{ref:"Psalm 34:14",L:"S",scripture:"“Seek peace, and pursue it.”",reflect:"Peace is worth chasing after — being a helper who calms things down and makes friends.",q:"How can you chase after peace today?",pray:"Help me seek peace, God, and be a calm and gentle friend."},
{ref:"Matthew 6:33",L:"S",scripture:"“Seek first God’s Kingdom and his righteousness.”",reflect:"When we put God first, everything else falls into the right place.",q:"How can you put God first today?",pray:"Help me put You first, God, in all that I think and do."},
{ref:"Psalm 23:6",L:"S",scripture:"“Surely goodness and loving kindness shall follow me all the days of my life.”",reflect:"God’s goodness follows us everywhere, like a friend who never leaves our side.",q:"Where has God’s goodness followed you today?",pray:"Thank You God that Your goodness follows me every single day."},
{ref:"Ephesians 5:1",L:"B",scripture:"“Be therefore imitators of God, as beloved children.”",reflect:"To imitate means to copy. We can copy God by being loving and kind.",q:"What kind thing can you copy from God today?",pray:"Help me be like You, God — loving, kind, and good."},
{ref:"Psalm 66:1",L:"M",scripture:"“Make a joyful shout to God, all the earth!”",reflect:"Praising God can be loud and joyful — like a happy cheer for the King of everything!",q:"Can you give God a joyful cheer?",pray:"Hooray for You, God! I shout for joy because You are wonderful."},
{ref:"Proverbs 14:31",L:"H",scripture:"“He who has mercy on the needy honours him.”",reflect:"Being kind to people who are struggling is a beautiful way to honour God.",q:"Who can you show mercy and kindness to today?",pray:"Help me be kind to those in need, God, and honour You."},
{ref:"Psalm 51:12",L:"R",scripture:"“Restore to me the joy of your salvation.”",reflect:"If our joy feels lost, we can ask God to bring it back. He fills us up again.",q:"What brings joy back to your heart?",pray:"Bring back my joy, God, and fill my heart with gladness."},
{ref:"John 10:11",L:"I",scripture:"“I am the good shepherd. The good shepherd lays down his life for the sheep.”",reflect:"Jesus is our Good Shepherd who loves us so much He gave everything to keep us safe.",q:"How does a good shepherd care for the sheep?",pray:"Thank You Jesus for being my Good Shepherd who loves me so much."},
{ref:"Psalm 40:1",L:"I",scripture:"“I waited patiently for Yahweh. He… heard my cry.”",reflect:"Sometimes we wait for God’s help. He always hears us and comes at just the right time.",q:"What is something worth waiting patiently for?",pray:"Help me wait patiently for You, God. Thank You for hearing me."},
{ref:"1 Thessalonians 5:11",L:"E",scripture:"“Encourage one another, and build each other up.”",reflect:"Encouraging words are like building blocks that help others feel strong and happy.",q:"Who can you encourage with kind words today?",pray:"Help me build others up, God, with cheerful, encouraging words."},
{ref:"Psalm 119:11",L:"Y",scripture:"“I have hidden your word in my heart, that I might not sin against you.”",reflect:"When we learn Bible verses, they stay in our hearts and help us do what’s right.",q:"What Bible verse would you like to remember?",pray:"Help me keep Your words in my heart, God, to guide me each day."},
{ref:"Proverbs 20:11",L:"E",scripture:"“Even a child makes himself known by his doings.”",reflect:"Even little ones show their good hearts by their kind and honest actions.",q:"What good action can you be known for today?",pray:"Help my actions show a kind and honest heart, God."},
{ref:"Psalm 95:2",L:"L",scripture:"“Let’s come before his presence with thanksgiving.”",reflect:"We can come to God with a thankful heart, ready to say how grateful we are.",q:"What are you most thankful for today?",pray:"I come to You with thanks, God. Thank You for all You give."},
{ref:"Matthew 7:7",L:"A",scripture:"“Ask, and it will be given to you… knock, and it will be opened for you.”",reflect:"God invites us to ask Him for help. He loves it when we come to Him.",q:"What can you ask God for help with today?",pray:"Thank You God that I can ask You for anything. Please help me."},
{ref:"Psalm 68:19",L:"B",scripture:"“Blessed be the Lord, who daily bears our burdens.”",reflect:"Every single day, God helps carry whatever feels heavy for us.",q:"What can God help you carry today?",pray:"Thank You God for carrying my burdens every single day."},
{ref:"1 Corinthians 13:13",L:"N",scripture:"“Now faith, hope, and love remain… The greatest of these is love.”",reflect:"Of all the good things, love is the greatest. Love lasts forever.",q:"Why do you think love is the greatest?",pray:"Fill me with faith, hope, and love, God — especially love."},
{ref:"Psalm 139:23",L:"S",scripture:"“Search me, God, and know my heart.”",reflect:"We can ask God to look at our hearts and help us grow kinder and better.",q:"What would you like God to help your heart with?",pray:"Search my heart, God, and help me become more like You."},
{ref:"Nehemiah 8:10",L:"T",scripture:"“The joy of Yahweh is your strength.”",reflect:"Being happy in God actually makes us strong inside, ready for anything.",q:"How does being joyful help you feel strong?",pray:"Thank You God that Your joy makes me strong and glad."},
{ref:"Psalm 37:7",L:"R",scripture:"“Rest in Yahweh, and wait patiently for him.”",reflect:"We can rest quietly and wait for God, trusting He will help at just the right time.",q:"What is something you can wait for patiently with God?",pray:"Help me rest and wait patiently for You, God. You are never late."},
/* ===== JUNE ===== */
{ref:"Psalm 127:3",L:"C",scripture:"“Behold, children are a heritage of Yahweh.”",reflect:"Children are a special gift from God to their families — and that means you!",q:"Why do you think God gives families children?",pray:"Thank You God for making me a gift to my family."},
{ref:"Ephesians 6:2",L:"H",scripture:"“Honour your father and mother… that it may be well with you.”",reflect:"Honouring our parents brings blessing and helps things go well for us.",q:"How can you honour Mummy and Daddy today?",pray:"Help me honour my parents, God, with love and respect."},
{ref:"Proverbs 23:24",L:"T",scripture:"“The father of the righteous has great joy.”",reflect:"When we choose to do right, it brings big joy to our parents’ hearts.",q:"What good choice can bring joy to your family today?",pray:"Help me make good choices, God, that bring my family joy."},
{ref:"Psalm 128:1",L:"B",scripture:"“Blessed is everyone who fears Yahweh, who walks in his ways.”",reflect:"Walking in God’s ways — being loving and honest — brings blessing to our whole family.",q:"What is one of God’s good ways you can walk in today?",pray:"Help our family walk in Your ways, God, and be blessed."},
{ref:"Colossians 3:14",L:"A",scripture:"“Above all… put on love, which is the bond of perfection.”",reflect:"Love is like a special glue that holds a family together perfectly.",q:"How can love hold your family together today?",pray:"Wrap our family in Your love, God, and hold us close together."},
{ref:"Psalm 133:3",L:"F",scripture:"“For there Yahweh gives the blessing, even life forever more.”",reflect:"When families live in peace, God pours out His blessing on them.",q:"How can you help bring peace to your home?",pray:"Bless our home with peace, God, and help us love each other."},
{ref:"1 Timothy 4:12",L:"D",scripture:"“Be an example… in word, in your way of life, in love, in faith.”",reflect:"Even little ones can be a good example by being loving, honest, and kind.",q:"How can you be a good example today?",pray:"Help me be a good example, God, in the way I live and love."},
{ref:"Psalm 78:4",L:"W",scripture:"“Telling to the generation to come the praises of Yahweh.”",reflect:"We can share the wonderful things God has done with our family and friends.",q:"What wonderful thing about God can you tell someone?",pray:"Help me tell others about Your greatness, God."},
{ref:"Proverbs 1:8",L:"M",scripture:"“My son, listen to your father’s instruction, and don’t forsake your mother’s teaching.”",reflect:"The wise things our parents teach us are worth listening to and remembering.",q:"What good thing have your parents taught you?",pray:"Help me listen to my parents, God, and remember their wise words."},
{ref:"Psalm 112:1",L:"B",scripture:"“Blessed is the man who fears Yahweh, who delights greatly in his commandments.”",reflect:"Loving God and being happy to follow Him brings a life full of blessing.",q:"What is one of God’s good rules you’re happy to follow?",pray:"Help me delight in Your good ways, God, with a happy heart."},
{ref:"Deuteronomy 6:5",L:"Y",scripture:"“You shall love Yahweh your God with all your heart.”",reflect:"Loving God with our whole heart is the most important thing we can ever do.",q:"How can you love God with your whole heart today?",pray:"I love You with all my heart, God. Help me love You more each day."},
{ref:"Psalm 111:10",L:"T",scripture:"“The fear of Yahweh is the beginning of wisdom.”",reflect:"Being wise starts with loving and respecting God. He helps us make good choices.",q:"What is a wise choice you can make today?",pray:"Help me be wise, God, by loving and following You."},
{ref:"James 1:17",L:"E",scripture:"“Every good gift and every perfect gift is from above.”",reflect:"All the good things in our lives come down to us from our loving God.",q:"What good gift are you thankful for today?",pray:"Thank You God that every good gift comes from You."},
{ref:"Psalm 37:23",L:"A",scripture:"“A man’s steps are established by Yahweh.”",reflect:"God helps guide our steps, leading us along the right path each day.",q:"Where might God be guiding your steps today?",pray:"Guide my steps, God, and lead me in Your good way."},
{ref:"Proverbs 13:20",L:"O",scripture:"“One who walks with wise men grows wise.”",reflect:"Spending time with good, wise people helps us grow wise and kind too.",q:"Who helps you learn good things?",pray:"Thank You God for wise people who help me grow. Make me wise too."},
{ref:"Psalm 19:14",L:"L",scripture:"“Let the words of my mouth… be acceptable in your sight, Yahweh.”",reflect:"We can ask God to help our words be kind and pleasing to Him.",q:"How can your words please God today?",pray:"Help my words be kind and good, God, and pleasing to You."},
{ref:"Matthew 25:40",L:"I",scripture:"“Just as you did it to one of the least of these… you did it to me.”",reflect:"When we help someone small or in need, Jesus says we are helping Him.",q:"Who is someone small or in need you can help?",pray:"Help me care for others, Jesus, knowing I’m serving You."},
{ref:"Psalm 89:1",L:"I",scripture:"“I will sing of the loving kindness of Yahweh forever.”",reflect:"God’s love is so good that we could sing about it forever and never run out.",q:"What song can you sing about God’s love?",pray:"I will sing about Your love forever, God. It never ends!"},
{ref:"Philippians 4:6",L:"D",scripture:"“In nothing be anxious, but… let your requests be made known to God.”",reflect:"Instead of worrying, we can talk to God about everything, and He gives us peace.",q:"What can you tell God instead of worrying?",pray:"Instead of worrying, God, I’ll talk to You. Thank You for peace."},
{ref:"Psalm 27:14",L:"W",scripture:"“Wait for Yahweh. Be strong, and let your heart take courage.”",reflect:"Waiting for God takes courage, but He always comes through at the right time.",q:"What is something worth waiting for with a brave heart?",pray:"Help me wait for You bravely, God, with a strong heart."},
{ref:"Romans 12:12",L:"R",scripture:"“Rejoicing in hope; enduring in troubles; continuing steadfastly in prayer.”",reflect:"We can stay happy in hope, brave in hard times, and always keep praying.",q:"How can you keep praying every day?",pray:"Help me stay hopeful, brave, and full of prayer, God."},
{ref:"Psalm 65:11",L:"Y",scripture:"“You crown the year with your bounty. Your paths overflow with abundance.”",reflect:"God fills the year with good things — food, seasons, and countless blessings.",q:"What good things has this year brought you?",pray:"Thank You God for filling our year with so many good things."},
{ref:"Proverbs 22:9",L:"H",scripture:"“He who has a generous eye will be blessed, for he shares his bread.”",reflect:"Sharing what we have with others is a happy thing that God loves and blesses.",q:"What can you share with someone today?",pray:"Help me be generous, God, and share with a happy heart."},
{ref:"Psalm 9:1",L:"I",scripture:"“I will give thanks to Yahweh with my whole heart.”",reflect:"We can thank God with everything in us, not just a little, but our whole hearts.",q:"What can you thank God for with your whole heart?",pray:"I thank You with my whole heart, God, for all You are and do."},
{ref:"Matthew 5:8",L:"B",scripture:"“Blessed are the pure in heart, for they shall see God.”",reflect:"A pure heart is a clean, honest, loving heart — and it helps us see God at work.",q:"How can you keep your heart clean and kind today?",pray:"Make my heart pure and kind, God, so I can see You more."},
{ref:"Psalm 145:2",L:"E",scripture:"“Every day I will praise you.”",reflect:"Praising God isn’t just for special days — we can praise Him every single day.",q:"How will you praise God today?",pray:"Every day I want to praise You, God. You are always good."},
{ref:"1 John 2:10",L:"H",scripture:"“He who loves his brother remains in the light.”",reflect:"Loving our brothers, sisters, and friends keeps us walking in God’s bright light.",q:"How can you love your brother or sister today?",pray:"Help me love my family, God, and stay in Your light."},
{ref:"Psalm 63:3",L:"B",scripture:"“Because your loving kindness is better than life, my lips shall praise you.”",reflect:"God’s love is even better than all the best things in life. It’s worth praising Him!",q:"What is one of the best things about God’s love?",pray:"Your love is the best, God. My lips will praise You today."},
{ref:"Proverbs 15:33",L:"T",scripture:"“The fear of Yahweh teaches wisdom. Before honour is humility.”",reflect:"Being humble — not boasting — is the wise and good way that leads to honour.",q:"How can you be humble and kind today?",pray:"Help me be humble and wise, God, and follow Your good ways."},
{ref:"1 John 4:18",L:"T",scripture:"“There is no fear in love; but perfect love casts out fear.”",reflect:"God’s perfect love is so big it chases away our fears, like light chasing shadows.",q:"How does God’s love help you feel brave?",pray:"Thank You God that Your perfect love takes all my fears away."},
/* ===== JULY ===== */
{ref:"Psalm 33:12",L:"B",scripture:"“Blessed is the nation whose God is Yahweh.”",reflect:"When people trust God together, it brings blessing to families and nations.",q:"How can your family put God first?",pray:"Bless our family and our land, God, as we trust in You."},
{ref:"Galatians 5:1",L:"F",scripture:"“For freedom, Christ has set us free.”",reflect:"Jesus makes us truly free — free to love, forgive, and live with joy.",q:"What does it feel like to be free and happy?",pray:"Thank You Jesus for setting me free to love and live with joy."},
{ref:"Psalm 119:32",L:"I",scripture:"“I run in the path of your commands, for you have set my heart free.”",reflect:"Following God’s good ways doesn’t weigh us down — it sets our hearts free to run with joy.",q:"How does following God make you feel happy and free?",pray:"Thank You God that Your ways set my heart free. Help me follow gladly."},
{ref:"2 Corinthians 9:7",L:"G",scripture:"“God loves a cheerful giver.”",reflect:"When we give and share with a happy heart, it makes God smile.",q:"What can you give cheerfully today?",pray:"Help me give with a cheerful heart, God, the way You love."},
{ref:"Psalm 47:1",L:"O",scripture:"“Oh clap your hands, all you nations. Shout to God with the voice of triumph!”",reflect:"We can celebrate God with clapping and cheering, like a big happy party!",q:"Can you clap your hands and cheer for God?",pray:"I clap and cheer for You, God! You are great and worth celebrating."},
{ref:"Proverbs 17:22",L:"A",scripture:"“A cheerful heart makes good medicine.”",reflect:"A happy heart and a good laugh can make us and others feel better.",q:"What makes you laugh and smile?",pray:"Thank You God for laughter and joy. Give me a cheerful heart."},
{ref:"Psalm 92:4",L:"F",scripture:"“For you, Yahweh, have made me glad through your work.”",reflect:"Looking at all the wonderful things God has made fills our hearts with gladness.",q:"What has God made that makes you glad?",pray:"Thank You God for all You’ve made. It fills me with gladness."},
{ref:"Matthew 6:34",L:"D",scripture:"“Therefore don’t be anxious for tomorrow.”",reflect:"We don’t need to worry about tomorrow — God will take care of us then, just like today.",q:"Why don’t we need to worry about tomorrow?",pray:"Help me not to worry, God. You take care of me every day."},
{ref:"Psalm 71:8",L:"M",scripture:"“My mouth shall be filled with your praise, and with your honour all day long.”",reflect:"We can fill our whole day with praises and thank-yous to God.",q:"How can you praise God throughout your day?",pray:"Fill my mouth with praise, God, all day long."},
{ref:"1 Peter 3:8",L:"B",scripture:"“Be all like-minded, compassionate, loving as brothers, tenderhearted, humble.”",reflect:"God wants us to be caring, loving, gentle, and humble with one another.",q:"Which of these can you show your family today?",pray:"Help me be caring, loving, and gentle, God, with everyone."},
{ref:"Psalm 121:1",L:"I",scripture:"“I will lift up my eyes to the hills. Where does my help come from?”",reflect:"When we need help, we look up to God, who made everything and helps us.",q:"Where do you look for help? God is our great helper.",pray:"I look to You for help, God. Thank You for always being there."},
{ref:"Proverbs 3:3",L:"D",scripture:"“Don’t let kindness and truth forsake you. Bind them around your neck.”",reflect:"We can wear kindness and truth like a special necklace we never take off.",q:"How can you keep kindness and truth close today?",pray:"Help me hold onto kindness and truth always, God."},
{ref:"Psalm 34:4",L:"I",scripture:"“I sought Yahweh, and he answered me, and delivered me from all my fears.”",reflect:"When we look for God in scary times, He answers and takes our fears away.",q:"What fear can God help you with?",pray:"Thank You God for answering me and taking away my fears."},
{ref:"John 6:35",L:"I",scripture:"“I am the bread of life. Whoever comes to me will not be hungry.”",reflect:"Jesus fills up our hearts the way bread fills a hungry tummy. He is all we need.",q:"How does Jesus fill up our hearts?",pray:"Thank You Jesus for filling my heart. You are all I need."},
{ref:"Psalm 100:3",L:"K",scripture:"“Know that Yahweh, he is God. He has made us, and we are his.”",reflect:"God made us, and we belong to Him. We are His special people.",q:"How does it feel to belong to God?",pray:"Thank You God for making me. I’m so glad I belong to You."},
{ref:"Romans 12:18",L:"I",scripture:"“If it is possible… be at peace with all men.”",reflect:"As much as we can, we should try to get along and be peaceful with everyone.",q:"How can you be peaceful with others today?",pray:"Help me live in peace with everyone, God, as much as I can."},
{ref:"Psalm 86:15",L:"B",scripture:"“You, Lord, are… full of compassion, gracious, slow to anger, and abundant in… kindness.”",reflect:"God is overflowing with kindness and patience. His love is endless.",q:"How is God patient and kind with you?",pray:"Thank You God for being so patient and full of kindness."},
{ref:"Proverbs 25:11",L:"A",scripture:"“A word fitly spoken is like apples of gold in settings of silver.”",reflect:"The right kind word at the right time is precious and beautiful, like treasure.",q:"What kind word can you give someone today?",pray:"Help me say the right kind words, God, at just the right time."},
{ref:"Psalm 91:1",L:"H",scripture:"“He who dwells in the secret place of the Most High will rest… under the shadow of the Almighty.”",reflect:"Staying close to God is like resting in a safe, cosy, shady spot.",q:"Where do you feel safe and restful?",pray:"Thank You God for being my safe and restful hiding place."},
{ref:"Ephesians 3:17",L:"T",scripture:"“That Christ may dwell in your hearts through faith… rooted and grounded in love.”",reflect:"When Jesus lives in our hearts, we grow strong roots in His love, like a healthy tree.",q:"How can you grow strong in Jesus’ love?",pray:"Live in my heart, Jesus, and root me deep in Your love."},
{ref:"Psalm 148:3",L:"P",scripture:"“Praise him, sun and moon! Praise him, all you shining stars!”",reflect:"Even the sun, moon, and stars praise God. We can join their happy song!",q:"What in the sky reminds you to praise God?",pray:"Like the stars, God, I praise You. You made everything shine!"},
{ref:"Matthew 22:37",L:"Y",scripture:"“You shall love the Lord your God with all your heart, soul, and mind.”",reflect:"We can love God with our feelings, our whole self, and our thoughts — every part of us.",q:"What are all the ways you can love God?",pray:"I love You with all of me, God — my heart, soul, and mind."},
{ref:"Psalm 40:8",L:"I",scripture:"“I delight to do your will, my God.”",reflect:"Doing what God wants can be a happy thing that brings us joy.",q:"What good thing can you happily do for God today?",pray:"I delight to do Your will, God. Help me follow You gladly."},
{ref:"Proverbs 16:20",L:"W",scripture:"“Whoever trusts in Yahweh is blessed.”",reflect:"Trusting God brings us blessing and a happy, peaceful heart.",q:"What can you trust God with today?",pray:"I trust in You, God. Thank You for Your blessing and peace."},
{ref:"Psalm 143:6",L:"I",scripture:"“I spread out my hands to you. My soul thirsts for you.”",reflect:"Our hearts reach out for God like open hands, wanting to be near Him.",q:"How can you reach out to God today?",pray:"I reach out my hands to You, God. My heart wants to be near You."},
{ref:"1 John 4:11",L:"B",scripture:"“If God loved us in this way, we also ought to love one another.”",reflect:"Because God loves us so much, we can pass that love on to each other.",q:"Who can you pass God’s love on to today?",pray:"Thank You for loving me, God. Help me love others the same way."},
{ref:"Psalm 118:6",L:"Y",scripture:"“Yahweh is on my side. I will not be afraid.”",reflect:"With God on our side, we don’t need to be afraid of anything.",q:"How does it help to know God is on your side?",pray:"Thank You God for being on my side. I won’t be afraid."},
{ref:"Colossians 4:2",L:"C",scripture:"“Continue steadfastly in prayer, watching in it with thanksgiving.”",reflect:"Keeping up our prayers, with thankful hearts, keeps us close to God.",q:"What can you thank God for in your prayers today?",pray:"Help me keep praying, God, with a thankful, watching heart."},
{ref:"Psalm 100:4",L:"E",scripture:"“Enter into his gates with thanksgiving… Give thanks to him.”",reflect:"We come close to God with thank-yous, like walking through a happy gate of gratitude.",q:"What thank-you will you bring to God today?",pray:"I come to You with thanks, God. Thank You for all Your gifts."},
{ref:"Proverbs 28:20",L:"A",scripture:"“A faithful man is rich in blessings.”",reflect:"Being faithful — doing what’s right and keeping our promises — brings many blessings.",q:"What promise can you keep today?",pray:"Help me be faithful and true, God, in everything I do."},
{ref:"Psalm 30:12",L:"Y",scripture:"“Yahweh my God, I will give thanks to you forever!”",reflect:"We can promise to thank God forever, because His goodness never ends.",q:"What will you thank God for forever?",pray:"I will thank You forever, God! You are always so good to me."},
/* ===== AUGUST ===== */
{ref:"Psalm 96:4",L:"F",scripture:"“For Yahweh is great, and greatly to be praised.”",reflect:"God is bigger and greater than anything we can imagine — worthy of all our praise.",q:"How big and great is God?",pray:"You are so great, God! I want to praise You with all my heart."},
{ref:"Proverbs 16:7",L:"W",scripture:"“When a man’s ways please Yahweh, he makes even his enemies to be at peace.”",reflect:"When we live God’s way, He can even turn arguments into peace.",q:"How can pleasing God bring peace around you?",pray:"Help me live in a way that pleases You, God, and brings peace."},
{ref:"Psalm 62:1",L:"M",scripture:"“My soul rests in God alone. My salvation is from him.”",reflect:"Our hearts find their truest rest and calm in God alone.",q:"What helps your heart feel calm and rested?",pray:"My heart rests in You, God. Thank You for keeping me calm."},
{ref:"Matthew 5:44",L:"L",scripture:"“Love your enemies… pray for those who persecute you.”",reflect:"Even when someone is unkind, we can choose to love them and pray for them.",q:"How can you be kind to someone who was unkind?",pray:"Help me love even those who are unkind, God, and pray for them."},
{ref:"Psalm 42:11",L:"W",scripture:"“Hope in God! For I shall still praise him.”",reflect:"When we feel down, we can lift our hearts with hope and keep praising God.",q:"What can you hope in God for today?",pray:"I put my hope in You, God, and I will keep praising You."},
{ref:"1 Corinthians 10:31",L:"W",scripture:"“Whatever you do, do all to the glory of God.”",reflect:"Even eating, playing, and helping can bring glory to God when we do them with love.",q:"How can your play or work bring glory to God?",pray:"Help me do everything for Your glory, God, big and small."},
{ref:"Psalm 145:16",L:"Y",scripture:"“You open your hand, and satisfy the desire of every living thing.”",reflect:"God opens His hand and gives food and good things to every creature He made.",q:"How does God take care of animals and people?",pray:"Thank You God for opening Your hand and giving us all we need."},
{ref:"Proverbs 14:21",L:"H",scripture:"“He who has pity on the poor, happy is he.”",reflect:"Being kind to those who have less brings real happiness to our hearts.",q:"How can you be kind to someone who needs help?",pray:"Help me be kind to those in need, God, with a happy heart."},
{ref:"Psalm 32:7",L:"Y",scripture:"“You are my hiding place. You will preserve me from trouble.”",reflect:"God is a safe hiding place where we can go whenever we feel worried or scared.",q:"Where do you go when you feel worried?",pray:"Thank You God for being my safe hiding place in every trouble."},
{ref:"John 15:11",L:"T",scripture:"“That my joy may remain in you, and that your joy may be made full.”",reflect:"Jesus wants us to be full of joy — the deep, happy kind that stays even on hard days.",q:"What fills you with joy?",pray:"Thank You Jesus for filling me with joy that stays."},
{ref:"Psalm 150:1",L:"P",scripture:"“Praise Yah! Praise God in his sanctuary!”",reflect:"We can praise God everywhere — at home, outside, and wherever we go.",q:"Where is your favourite place to praise God?",pray:"I praise You, God, everywhere I go. You are wonderful!"},
{ref:"Romans 8:38",L:"F",scripture:"“Neither death, nor life… will be able to separate us from the love of God.”",reflect:"Nothing in the whole world can ever pull us away from God’s love. It holds us forever.",q:"What can separate you from God’s love? Nothing at all!",pray:"Thank You God that nothing can ever separate me from Your love."},
{ref:"Psalm 33:20",L:"O",scripture:"“Our soul has waited for Yahweh. He is our help and our shield.”",reflect:"We wait for God with hope, knowing He helps us and keeps us safe.",q:"How is God your helper and your shield?",pray:"Thank You God for being my help and my shield. I wait for You."},
{ref:"Proverbs 12:18",L:"K",scripture:"“The tongue of the wise heals.”",reflect:"Wise, kind words can heal hurt feelings and make people feel better.",q:"How can your words heal someone today?",pray:"Help my words be wise and healing, God, bringing comfort."},
{ref:"Psalm 89:8",L:"O",scripture:"“Yahweh, God of Armies, who is a mighty one, like you?”",reflect:"There is no one anywhere as mighty and wonderful as our God.",q:"What makes God stronger than anything?",pray:"There is no one like You, God! You are mighty and wonderful."},
{ref:"Matthew 21:16",L:"O",scripture:"“Out of the mouth of babes and nursing babies you have perfected praise.”",reflect:"Even the littlest children can praise God perfectly. Your praise is precious to Him.",q:"How can even little ones praise God?",pray:"Thank You God that even my small praise is precious to You."},
{ref:"Psalm 63:1",L:"O",scripture:"“God, you are my God. I will earnestly seek you.”",reflect:"We can look for God each morning, wanting to be close to Him all day.",q:"How can you seek God today?",pray:"You are my God. I will look for You and seek You each day."},
{ref:"1 Peter 2:17",L:"H",scripture:"“Honour all men. Love the brotherhood.”",reflect:"God asks us to treat everyone with respect and to love our family and friends.",q:"How can you show respect to someone today?",pray:"Help me honour everyone, God, and love those around me."},
{ref:"Psalm 34:13",L:"K",scripture:"“Keep your tongue from evil, and your lips from speaking lies.”",reflect:"We can choose to speak truth and kindness, keeping unkind words away.",q:"How can you speak truth and kindness today?",pray:"Help me speak truth and kind words, God, all day long."},
{ref:"Isaiah 26:3",L:"Y",scripture:"“You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.”",reflect:"When we keep our minds on God, He fills us with perfect, calm peace.",q:"How can you keep your mind on God today?",pray:"Keep my mind on You, God, and fill me with perfect peace."},
{ref:"Psalm 104:24",L:"Y",scripture:"“Yahweh, how many are your works! In wisdom you have made them all.”",reflect:"God made everything with great wisdom — every animal, plant, and star.",q:"What has God made that amazes you?",pray:"Thank You God for making everything so wisely and wonderfully."},
{ref:"Proverbs 11:2",L:"W",scripture:"“With humility comes wisdom.”",reflect:"Being humble — not showing off — helps us grow wise and kind.",q:"How can you be humble today?",pray:"Help me be humble, God, and grow wise in Your good ways."},
{ref:"Psalm 118:8",L:"I",scripture:"“It is better to take refuge in Yahweh, than to put confidence in man.”",reflect:"Trusting God is even safer and better than trusting in anything else.",q:"Why is it good to trust God most of all?",pray:"Help me trust You most of all, God. You are my safe place."},
{ref:"John 14:15",L:"I",scripture:"“If you love me, keep my commandments.”",reflect:"One way we show Jesus we love Him is by obeying His good and loving ways.",q:"How can you show Jesus you love Him today?",pray:"I love You, Jesus. Help me follow Your good ways to show it."},
{ref:"Psalm 116:12",L:"W",scripture:"“What will I give to Yahweh for all his benefits toward me?”",reflect:"God gives us so much! We can give back our love, our praise, and our whole hearts.",q:"What can you give back to God today?",pray:"Thank You for all You give, God. I give You my love and praise."},
{ref:"Ephesians 4:29",L:"L",scripture:"“Let no corrupt speech proceed out of your mouth, but… what is good.”",reflect:"We can choose to say good, building-up words instead of unkind ones.",q:"What good words can you say today?",pray:"Help only good, kind words come from my mouth, God."},
{ref:"Psalm 138:1",L:"I",scripture:"“I will give you thanks with my whole heart.”",reflect:"We can thank God with everything in us, holding nothing back.",q:"What can you thank God for with your whole heart?",pray:"I thank You with my whole heart, God, for all Your love."},
{ref:"Proverbs 21:21",L:"H",scripture:"“He who follows after righteousness and kindness finds life… and honour.”",reflect:"Chasing after goodness and kindness leads to a happy, blessed life.",q:"How can you chase after kindness today?",pray:"Help me follow after goodness and kindness, God, every day."},
{ref:"Psalm 143:5",L:"I",scripture:"“I remember the days of old. I meditate on all your doings.”",reflect:"Remembering the good things God has done fills us with thankfulness and trust.",q:"What good thing has God done that you can remember?",pray:"Help me remember Your goodness, God, and trust You more."},
{ref:"Matthew 6:21",L:"F",scripture:"“For where your treasure is, there your heart will be also.”",reflect:"What we love most shows where our hearts truly are. Loving God is the best treasure.",q:"What is the best treasure to love?",pray:"Help my heart treasure You most of all, God."},
{ref:"Psalm 81:1",L:"S",scripture:"“Sing aloud to God, our strength! Shout for joy to the God of Jacob!”",reflect:"We can shout for joy to God with happy, thankful hearts.",q:"Can you shout a happy ‘thank You’ to God?",pray:"I shout for joy to You, God! Thank You for being so good."},
/* ===== SEPTEMBER ===== */
{ref:"Proverbs 2:6",L:"F",scripture:"“For Yahweh gives wisdom. Out of his mouth comes knowledge and understanding.”",reflect:"When we need to learn or understand, we can ask God, who gives wisdom.",q:"What would you like God to help you understand?",pray:"Thank You God for giving wisdom. Help me learn and understand."},
{ref:"Psalm 25:5",L:"G",scripture:"“Guide me in your truth, and teach me.”",reflect:"As we start new things, we can ask God to guide us and teach us His truth.",q:"What new thing can God help you with?",pray:"Guide me and teach me, God, in Your truth today."},
{ref:"Colossians 3:16",L:"L",scripture:"“Let the word of Christ dwell in you richly.”",reflect:"When we fill up with Jesus’ words, our hearts grow rich with love and wisdom.",q:"What Bible words can you keep in your heart?",pray:"Fill my heart with Your words, Jesus, so I grow in love."},
{ref:"Psalm 90:12",L:"T",scripture:"“Teach us to count our days, that we may gain a heart of wisdom.”",reflect:"Every day is precious. Using our days well makes our hearts wise.",q:"How can you use today well for God?",pray:"Help me use each day well, God, and grow a wise heart."},
{ref:"1 Corinthians 15:58",L:"B",scripture:"“Be steadfast, immovable, always abounding in the Lord’s work.”",reflect:"Keeping on doing good, even when it’s hard, is never wasted with God.",q:"What good work can you keep doing?",pray:"Help me keep doing good, God, and never give up."},
{ref:"Psalm 37:8",L:"C",scripture:"“Cease from anger, and forsake wrath.”",reflect:"When we feel cross, we can take a breath and let the anger go, choosing peace.",q:"What helps you calm down when you’re angry?",pray:"Help me let go of anger, God, and choose peace instead."},
{ref:"Proverbs 3:27",L:"D",scripture:"“Don’t withhold good from those to whom it is due, when it is in your power to do it.”",reflect:"When we are able to help or be kind, we shouldn’t hold back — we should do it.",q:"What good can you do for someone today?",pray:"Help me do good whenever I can, God, without holding back."},
{ref:"Psalm 119:66",L:"T",scripture:"“Teach me good judgment and knowledge, for I believe in your commandments.”",reflect:"We can ask God to help us make good, wise choices each day.",q:"What good choice can you ask God to help with?",pray:"Teach me to choose well, God, and follow Your good ways."},
{ref:"Matthew 5:37",L:"L",scripture:"“Let your ‘Yes’ be ‘Yes’ and your ‘No’ be ‘No.’”",reflect:"Being honest means meaning what we say — our yes is true and our no is true.",q:"How can you be honest with your words today?",pray:"Help me be honest, God, so my words can always be trusted."},
{ref:"Psalm 5:11",L:"L",scripture:"“Let all those who take refuge in you rejoice… shout for joy.”",reflect:"When we run to God for safety, our hearts can be filled with joy.",q:"What makes you feel joyful and safe with God?",pray:"I take refuge in You, God, and my heart shouts for joy!"},
{ref:"Galatians 6:2",L:"B",scripture:"“Bear one another’s burdens, and so fulfill the law of Christ.”",reflect:"Helping carry each other’s heavy loads is exactly what Jesus wants us to do.",q:"Whose heavy load can you help carry today?",pray:"Help me carry others’ burdens, God, with a loving heart."},
{ref:"Psalm 84:10",L:"F",scripture:"“For a day in your courts is better than a thousand.”",reflect:"One day close to God is better than a thousand days anywhere else.",q:"Why is being close to God so good?",pray:"Being with You, God, is the best. I love being close to You."},
{ref:"Proverbs 27:1",L:"D",scripture:"“Don’t boast about tomorrow, for you don’t know what a day may bring.”",reflect:"We don’t brag about what we’ll do — we humbly trust each day to God.",q:"How can you trust tomorrow to God?",pray:"Help me be humble, God, and trust each new day to You."},
{ref:"Psalm 121:3",L:"H",scripture:"“He… will not slumber. He who keeps you will not slumber.”",reflect:"God never falls asleep on the job — He watches over us all day and all night.",q:"How does it help to know God never sleeps?",pray:"Thank You God for watching over me, day and night, always."},
{ref:"John 13:35",L:"B",scripture:"“By this everyone will know that you are my disciples, if you have love for one another.”",reflect:"People can tell we belong to Jesus by how much we love each other.",q:"How can your love show that you follow Jesus?",pray:"Help me love others well, Jesus, so they see I belong to You."},
{ref:"Psalm 34:19",L:"M",scripture:"“Many are the afflictions of the righteous, but Yahweh delivers him out of them all.”",reflect:"Hard things happen to everyone, but God helps us through every single one.",q:"How does God help you through hard times?",pray:"Thank You God for helping me through every hard thing."},
{ref:"Proverbs 15:16",L:"B",scripture:"“Better is little with the fear of Yahweh, than great treasure with trouble.”",reflect:"Having a little with God’s peace is better than having lots without Him.",q:"Why is God’s peace better than lots of stuff?",pray:"Help me treasure You more than things, God. You are best."},
{ref:"Psalm 71:23",L:"M",scripture:"“My lips shall shout for joy! My soul… sings praises to you.”",reflect:"Our whole selves can burst with joyful songs of praise to God.",q:"What praise song makes you happy?",pray:"My heart sings for joy to You, God! You are so good."},
{ref:"1 John 1:9",L:"I",scripture:"“If we confess our sins, he is faithful… to forgive us.”",reflect:"When we tell God we’re sorry, He always forgives and makes us clean again.",q:"Why is it good to say sorry to God?",pray:"Thank You God that You always forgive me when I say sorry."},
{ref:"Psalm 46:2",L:"T",scripture:"“Therefore we won’t be afraid, though the earth changes.”",reflect:"Even if everything around us changes, God stays the same, so we don’t need to fear.",q:"What stays the same no matter what? God does!",pray:"Thank You God that You never change. I don’t need to be afraid."},
{ref:"Proverbs 19:20",L:"L",scripture:"“Listen to counsel and receive instruction, that you may be wise.”",reflect:"Listening to good advice from those who love us helps us grow wise.",q:"Who gives you good advice?",pray:"Help me listen well, God, and grow wise and kind."},
{ref:"Psalm 96:9",L:"W",scripture:"“Worship Yahweh in holy array.”",reflect:"Worshipping God means giving Him our love, respect, and thankful hearts.",q:"What does it mean to worship God?",pray:"I worship You, God, with all my heart. You are wonderful."},
{ref:"Romans 12:2",L:"D",scripture:"“Don’t be conformed to this world, but be transformed by the renewing of your mind.”",reflect:"God helps our hearts and minds become new and good, more like Jesus.",q:"How can God make your heart more like Jesus?",pray:"Change my heart, God, and help me become more like Jesus."},
{ref:"Psalm 138:8",L:"Y",scripture:"“Yahweh will fulfill that which concerns me.”",reflect:"God will complete the good plans He has for us. We can trust Him with our future.",q:"What good plan can you trust God with?",pray:"Thank You God for the good plans You have for me. I trust You."},
{ref:"Proverbs 17:9",L:"H",scripture:"“He who covers an offence promotes love.”",reflect:"Forgiving and letting go of hurts helps love grow between us.",q:"What hurt can you forgive to help love grow?",pray:"Help me forgive and let go, God, so love can grow."},
{ref:"Psalm 95:7",L:"I",scripture:"“For he is our God. We are the people of his pasture, and the sheep in his care.”",reflect:"We belong to God like sheep belong to their loving shepherd.",q:"How does it feel to belong to God?",pray:"Thank You God that I am Yours. I’m glad to be one of Your sheep."},
{ref:"Matthew 18:21",L:"H",scripture:"“Lord, how often shall… I forgive him? Until seventy times seven.”",reflect:"Jesus says to forgive again and again — as many times as it takes.",q:"How many times should we forgive? Lots and lots!",pray:"Help me forgive again and again, God, like You forgive me."},
{ref:"Psalm 145:14",L:"Y",scripture:"“Yahweh upholds all who fall, and raises up all those who are bowed down.”",reflect:"When we stumble or feel low, God lifts us back up with His strong, loving hands.",q:"How does God help you when you fall?",pray:"Thank You God for lifting me up whenever I stumble."},
{ref:"Proverbs 12:22",L:"L",scripture:"“Those who deal truly are his delight.”",reflect:"God is delighted when we are honest and truthful.",q:"How can you be truthful today?",pray:"Help me always tell the truth, God, and delight Your heart."},
{ref:"Psalm 92:2",L:"T",scripture:"“To proclaim your loving kindness in the morning, and your faithfulness every night.”",reflect:"We can thank God for His love in the morning and His faithfulness at night.",q:"How can you thank God morning and night?",pray:"Thank You for Your love each morning, God, and Your care each night."},
/* ===== OCTOBER ===== */
{ref:"Psalm 65:9",L:"Y",scripture:"“You visit the earth, and water it. You greatly enrich it.”",reflect:"God sends rain and sunshine to grow food from the earth. He provides for us all.",q:"What food are you thankful God provides?",pray:"Thank You God for rain, sun, and food from the earth."},
{ref:"James 1:22",L:"B",scripture:"“Be doers of the word, and not only hearers.”",reflect:"It’s good to hear God’s word — and even better to do what it says.",q:"What good thing can you do that God’s word teaches?",pray:"Help me not just hear Your word, God, but do it too."},
{ref:"Psalm 107:1",L:"G",scripture:"“Give thanks to Yahweh, for he is good, for his loving kindness endures forever.”",reflect:"Autumn is a lovely time to say thank You to God for His endless goodness.",q:"What are you thankful for this season?",pray:"Thank You God for Your goodness that never ever ends."},
{ref:"Proverbs 3:7",L:"D",scripture:"“Don’t be wise in your own eyes. Fear Yahweh, and depart from evil.”",reflect:"True wisdom comes from listening to God, not just thinking we know best.",q:"How can you ask God to help you be wise?",pray:"Help me be truly wise, God, by listening to You."},
{ref:"Psalm 34:10",L:"T",scripture:"“Those who seek Yahweh shall not lack any good thing.”",reflect:"When we look to God, He makes sure we have every good thing we truly need.",q:"How does God provide good things for you?",pray:"Thank You God for giving me every good thing I need."},
{ref:"Matthew 5:4",L:"B",scripture:"“Blessed are those who mourn, for they shall be comforted.”",reflect:"When we are sad, God promises to bring us comfort and gentle care.",q:"How does God comfort you when you’re sad?",pray:"Thank You God for comforting me whenever I feel sad."},
{ref:"Psalm 119:114",L:"Y",scripture:"“You are my hiding place and my shield. I hope in your word.”",reflect:"God’s promises are a safe place to hide and a shield to keep us strong.",q:"What promise of God makes you feel safe?",pray:"Thank You God for being my hiding place and my shield."},
{ref:"Philippians 2:14",L:"D",scripture:"“Do all things without complaining and arguing.”",reflect:"Doing our jobs happily, without grumbling, makes God and everyone glad.",q:"What can you do today without complaining?",pray:"Help me do things cheerfully, God, without grumbling."},
{ref:"Psalm 105:1",L:"G",scripture:"“Give thanks to Yahweh! Call on his name! Make his deeds known.”",reflect:"We can tell others about the wonderful things God has done for us.",q:"What has God done that you can tell someone about?",pray:"Help me tell others about the good things You do, God."},
{ref:"Proverbs 24:16",L:"F",scripture:"“For a righteous man falls seven times, and rises up again.”",reflect:"Everyone makes mistakes. What matters is getting back up and trying again with God.",q:"What can you try again, even after a mistake?",pray:"Help me get back up and try again, God, when I fall."},
{ref:"Psalm 62:5",L:"M",scripture:"“My soul, wait in silence for God alone, for my expectation is from him.”",reflect:"We can wait quietly and hopefully for God, knowing He will help.",q:"What are you hoping God will help you with?",pray:"I wait quietly for You, God. My hope comes from You alone."},
{ref:"1 John 4:12",L:"I",scripture:"“If we love one another, God remains in us, and his love is perfected in us.”",reflect:"When we love each other, God’s love grows complete and beautiful in our home.",q:"How can you help God’s love grow in your family?",pray:"Help us love one another, God, so Your love fills our home."},
{ref:"Psalm 145:3",L:"G",scripture:"“Great is Yahweh, and greatly to be praised! His greatness is unsearchable.”",reflect:"God is so great that we could never measure it all — He is greater than we know.",q:"How great do you think God is?",pray:"You are so great, God! I praise You with all my heart."},
{ref:"Matthew 19:26",L:"W",scripture:"“With God all things are possible.”",reflect:"Nothing is too hard for God. He can do things that seem impossible to us.",q:"What big thing can you trust God to help with?",pray:"Thank You God that with You, all things are possible."},
{ref:"Psalm 27:8",L:"Y",scripture:"“My heart said to you, ‘I will seek your face.’”",reflect:"Our hearts long to be near God, to look for Him and know Him more.",q:"How can you seek God with your heart today?",pray:"My heart wants to know You, God. Help me seek You each day."},
{ref:"Proverbs 15:29",L:"Y",scripture:"“He hears the prayer of the righteous.”",reflect:"God listens carefully to the prayers of those who love and follow Him.",q:"What prayer would you like God to hear today?",pray:"Thank You God for hearing my prayers. I love talking to You."},
{ref:"Psalm 33:22",L:"L",scripture:"“Let your loving kindness be on us, since we have hoped in you.”",reflect:"We can ask God to pour His kind love over us as we trust in Him.",q:"How has God shown you kind love?",pray:"Pour Your kind love over me, God. I put my hope in You."},
{ref:"Romans 15:13",L:"M",scripture:"“May the God of hope fill you with all joy and peace in believing.”",reflect:"God fills us with hope, joy, and peace when we trust in Him.",q:"What fills you with hope and joy?",pray:"Fill me with joy and peace, God of hope, as I trust You."},
{ref:"Psalm 71:14",L:"B",scripture:"“But I will always hope, and will add to all your praise.”",reflect:"We can keep hoping in God and keep adding more and more praise.",q:"What new praise can you give God today?",pray:"I will always hope in You, God, and praise You more and more."},
{ref:"Ephesians 4:15",L:"S",scripture:"“Speaking truth in love, we may grow up in all things.”",reflect:"Telling the truth in a kind, loving way helps us and others grow.",q:"How can you tell the truth kindly today?",pray:"Help me speak the truth with love, God, and grow good and strong."},
{ref:"Psalm 100:5b",L:"H",scripture:"“His faithfulness endures to all generations.”",reflect:"God has been faithful to families for all time — grandparents, parents, and children.",q:"How has God been faithful to your family?",pray:"Thank You God for being faithful to my family, always."},
{ref:"Proverbs 16:32",L:"H",scripture:"“He who is slow to anger is better than the mighty.”",reflect:"Staying calm and patient is even stronger than being big and powerful.",q:"How can you stay calm when you feel cross?",pray:"Help me be slow to anger, God, and gentle and calm."},
{ref:"Psalm 139:1",L:"Y",scripture:"“Yahweh, you have searched me, and you know me.”",reflect:"God knows everything about us — and He loves us completely anyway.",q:"How does it feel that God knows you fully and loves you?",pray:"Thank You God for knowing me completely and loving me so."},
{ref:"John 1:12",L:"A",scripture:"“As many as received him, to them he gave the right to become God’s children.”",reflect:"When we welcome Jesus into our hearts, we become part of God’s big family.",q:"What does it mean to be part of God’s family?",pray:"Thank You Jesus for making me part of God’s family."},
{ref:"Psalm 52:8",L:"I",scripture:"“I trust in God’s loving kindness forever and ever.”",reflect:"We can trust in God’s kind love forever — it will never let us down.",q:"Why can we always trust God’s love?",pray:"I trust in Your love forever, God. Thank You for never failing me."},
{ref:"Proverbs 22:11",L:"H",scripture:"“He who loves purity of heart and speaks graciously is the king’s friend.”",reflect:"A clean heart and kind words make us friends with God, the King of all.",q:"How can you have a clean heart and kind words today?",pray:"Give me a clean heart and gracious words, God."},
{ref:"Psalm 34:11",L:"C",scripture:"“Come, you children, listen to me. I will teach you the fear of Yahweh.”",reflect:"God loves to teach children how to know and love Him.",q:"What would you like to learn about God?",pray:"Teach me about You, God. I want to know and love You more."},
{ref:"1 Peter 5:6",L:"H",scripture:"“Humble yourselves… under the mighty hand of God.”",reflect:"Being humble means trusting God’s strong hand to lift us at the right time.",q:"How can you be humble and trust God today?",pray:"Help me be humble, God, and trust Your mighty, loving hand."},
{ref:"Psalm 143:1",L:"H",scripture:"“Hear my prayer, Yahweh. Listen to my petitions.”",reflect:"God always hears our prayers, even the quiet whispers of our hearts.",q:"What quiet prayer is in your heart?",pray:"Hear my prayer, God. Thank You for always listening to me."},
{ref:"Proverbs 3:24",L:"W",scripture:"“When you lie down, you will not be afraid… your sleep will be sweet.”",reflect:"We can sleep peacefully, knowing God watches over us all through the night.",q:"How does God help you sleep peacefully?",pray:"Thank You God for watching over me. Give me sweet, safe sleep."},
{ref:"Psalm 89:1b",L:"W",scripture:"“With my mouth I will make known your faithfulness to all generations.”",reflect:"We can tell everyone how faithful and trustworthy God always is.",q:"How can you tell others God is faithful?",pray:"Help me tell others how faithful You are, God, always and forever."},
/* ===== NOVEMBER ===== */
{ref:"Psalm 95:1",L:"C",scripture:"“Come, let’s sing to Yahweh. Let’s shout aloud to the rock of our salvation!”",reflect:"God is like a strong, steady rock. We can celebrate Him with joyful songs.",q:"What song can you sing to God today?",pray:"I sing to You, God, my strong rock! Thank You for saving me."},
{ref:"1 Chronicles 16:34",L:"O",scripture:"“Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.”",reflect:"A thankful heart is a happy heart. God’s love gives us so much to thank Him for.",q:"What are three big things you’re thankful for?",pray:"Thank You God for being so good. Your love lasts forever."},
{ref:"Psalm 92:1b",L:"T",scripture:"“To sing praises to your name, Most High.”",reflect:"Singing praise to God fills our hearts with joy and shows Him our love.",q:"What is your favourite way to praise God?",pray:"I love to sing Your praises, God. You are the Most High."},
{ref:"Colossians 3:15",L:"L",scripture:"“Let the peace of God rule in your hearts… and be thankful.”",reflect:"When God’s peace leads our hearts, thankfulness naturally grows inside us.",q:"How can you let peace and thanks fill your heart?",pray:"Let Your peace rule my heart, God, and make me thankful."},
{ref:"Psalm 136:26",L:"G",scripture:"“Give thanks to the God of heaven, for his loving kindness endures forever.”",reflect:"No matter what, God’s love keeps going forever. That’s worth thanking Him for daily.",q:"What thank-you can you say to God right now?",pray:"Thank You God of heaven! Your love never, ever ends."},
{ref:"Luke 17:15",L:"O",scripture:"“One of them, when he saw that he was healed, turned back… glorifying God.”",reflect:"When God does something good, remembering to say thank You makes His heart glad.",q:"Have you remembered to thank God for something good?",pray:"Help me always remember to say thank You, God, for Your kindness."},
{ref:"Psalm 107:8",L:"O",scripture:"“Let them praise Yahweh for his loving kindness, for his wonderful deeds.”",reflect:"God does wonderful things for us every day, worthy of our thanks and praise.",q:"What wonderful thing has God done for you?",pray:"I praise You God for Your kindness and Your wonderful works."},
{ref:"Philippians 1:3",L:"I",scripture:"“I thank my God whenever I remember you.”",reflect:"We can thank God for the special people in our lives — our family and friends.",q:"Who are you thankful God put in your life?",pray:"Thank You God for my family and friends. They are gifts to me."},
{ref:"Psalm 118:28",L:"Y",scripture:"“You are my God, and I will give thanks to you.”",reflect:"God is our God, and thanking Him keeps our hearts close to Him.",q:"Why is it good to thank God every day?",pray:"You are my God, and I thank You with all my heart."},
{ref:"Ephesians 5:20",L:"G",scripture:"“Giving thanks always… in the name of our Lord Jesus Christ.”",reflect:"We can give thanks all the time, for everything, in Jesus’ name.",q:"What is something small you can thank God for?",pray:"Help me give thanks always, God, for big and little things."},
{ref:"Psalm 100:4b",L:"B",scripture:"“Be thankful to him, and bless his name.”",reflect:"Being thankful and blessing God’s name is a beautiful daily habit.",q:"How can you bless God’s name today?",pray:"I bless Your name, God, and thank You for all You are."},
{ref:"1 Thessalonians 5:16",L:"R",scripture:"“Rejoice always.”",reflect:"We can choose joy every day, because God is always good and always with us.",q:"What can you rejoice about today?",pray:"Help me rejoice always, God, because You are so good."},
{ref:"Psalm 30:4",L:"S",scripture:"“Sing praise to Yahweh… and give thanks to his holy name.”",reflect:"Singing and thanking God go beautifully together, like a happy song of love.",q:"What can you sing thank-you to God for?",pray:"I sing and give thanks to You, God. Your name is holy and good."},
{ref:"Proverbs 30:8",L:"G",scripture:"“Feed me with the food that is needful for me.”",reflect:"We can thank God for giving us just what we need each day, like our daily food.",q:"What has God given you today that you need?",pray:"Thank You God for giving me just what I need each day."},
{ref:"Psalm 34:3",L:"O",scripture:"“Oh magnify Yahweh with me. Let’s exalt his name together.”",reflect:"We can praise God together as a family, making His name big in our home.",q:"How can your family praise God together?",pray:"Let’s praise You together, God! Your name is great and good."},
{ref:"2 Corinthians 9:15",L:"T",scripture:"“Thanks be to God for his unspeakable gift!”",reflect:"God’s greatest gift is Jesus — a gift so wonderful we can hardly find words.",q:"What is God’s best gift to us?",pray:"Thank You God for Jesus, Your best and most wonderful gift."},
{ref:"Psalm 111:1",L:"I",scripture:"“I will give thanks to Yahweh with my whole heart.”",reflect:"Whole-hearted thanks means thanking God with everything inside us.",q:"What can you thank God for with your whole heart?",pray:"I thank You with my whole heart, God, for all Your love."},
{ref:"James 1:5",L:"I",scripture:"“If any of you lacks wisdom, let him ask of God… and it will be given to him.”",reflect:"When we don’t know what to do, we can ask God for wisdom, and He gives it gladly.",q:"What can you ask God to help you understand?",pray:"Thank You God for giving wisdom. Help me when I don’t know what to do."},
{ref:"Psalm 145:15",L:"T",scripture:"“The eyes of all wait for you. You give them their food in due season.”",reflect:"Every creature looks to God for food, and He feeds them all at the right time.",q:"How does God feed all the animals and us?",pray:"Thank You God for feeding every creature, including me."},
{ref:"Colossians 2:7",L:"R",scripture:"“Rooted and built up in him… abounding in thanksgiving.”",reflect:"Growing strong in Jesus fills us up with overflowing thankfulness.",q:"How can you overflow with thanks today?",pray:"Root me deep in You, Jesus, and fill me with thankfulness."},
{ref:"Psalm 66:5",L:"C",scripture:"“Come, and see God’s deeds — awesome work on behalf of the children of men.”",reflect:"God does amazing things for people. Looking at them fills us with wonder.",q:"What amazing thing has God done that you can see?",pray:"Thank You God for Your awesome works. You amaze me!"},
{ref:"Proverbs 11:17",L:"T",scripture:"“The merciful man does good to his own soul.”",reflect:"When we are kind to others, it does good things inside our own hearts too.",q:"How does being kind make you feel?",pray:"Help me be merciful and kind, God. It’s good for my heart."},
{ref:"Psalm 106:1",L:"P",scripture:"“Praise Yah! Give thanks to Yahweh, for he is good.”",reflect:"Praising and thanking God is one of the happiest things we can do.",q:"What makes you want to praise God?",pray:"Praise You, God! You are good, and I give You thanks."},
{ref:"1 Timothy 6:6",L:"G",scripture:"“Godliness with contentment is great gain.”",reflect:"Being happy with what we have, plus loving God, is the richest life of all.",q:"What are you happy and content with today?",pray:"Help me be content, God, and thankful for what I have."},
{ref:"Psalm 92:5",L:"H",scripture:"“How great are your works, Yahweh! Your thoughts are very deep.”",reflect:"God’s works are great and His thoughts are deeper than the deepest ocean.",q:"What great work of God amazes you?",pray:"Your works are so great, God! I’m amazed by all You do."},
{ref:"Matthew 15:36",L:"H",scripture:"“He… gave thanks, broke… and gave to the disciples.”",reflect:"Even Jesus said thank You to God before meals. We can be thankful before we eat too.",q:"What do you say thank You to God for at mealtimes?",pray:"Thank You God for our food. Help us always be grateful."},
{ref:"Psalm 103:1",L:"P",scripture:"“Praise Yahweh, my soul! All that is within me, praise his holy name!”",reflect:"We can praise God with everything inside us — our whole heart and soul.",q:"How can you praise God with all that’s in you?",pray:"With all that is in me, God, I praise Your holy name!"},
{ref:"Deuteronomy 8:10",L:"W",scripture:"“You shall eat and be full, and you shall bless Yahweh your God.”",reflect:"When we have enough and feel full, it’s a perfect time to bless and thank God.",q:"What good things fill you up that you can thank God for?",pray:"Thank You God for filling us up. We bless and thank You."},
{ref:"Psalm 116:17",L:"I",scripture:"“I will offer to you the sacrifice of thanksgiving.”",reflect:"Our thank-yous are a gift we give to God, and He treasures them.",q:"What thank-you gift can you give God today?",pray:"I give You my thanks, God, as a gift from my grateful heart."},
{ref:"Psalm 126:3",L:"Y",scripture:"“Yahweh has done great things for us, and we are glad.”",reflect:"Looking back at all God has done fills our hearts with gladness and thanks.",q:"What great thing has God done for your family?",pray:"You have done great things for us, God, and we are so glad!"},
/* ===== DECEMBER ===== */
{ref:"Isaiah 9:6",L:"F",scripture:"“For a child is born to us… his name will be called Wonderful Counselor, Mighty God.”",reflect:"Long ago God promised a special child — Jesus! This month we celebrate His coming.",q:"What names does the Bible give to Jesus?",pray:"Thank You God for the promise of Jesus, our Wonderful Saviour."},
{ref:"Luke 1:37",L:"F",scripture:"“For nothing spoken by God is impossible.”",reflect:"The angel told Mary that nothing is impossible for God. He can do anything!",q:"What amazing thing can God do?",pray:"Thank You God that nothing is impossible for You."},
{ref:"Micah 5:2",L:"B",scripture:"“Bethlehem… out of you… will come… one who is to be ruler in Israel.”",reflect:"God planned exactly where Jesus would be born, hundreds of years before it happened.",q:"Where was Jesus born?",pray:"Thank You God for planning Jesus’ birth so carefully and lovingly."},
{ref:"Luke 1:46",L:"M",scripture:"“My soul magnifies the Lord.”",reflect:"Mary was so happy about Jesus that her heart burst with praise to God.",q:"What makes your heart happy about Jesus?",pray:"My heart praises You, God, for the gift of baby Jesus."},
{ref:"Isaiah 7:14",L:"B",scripture:"“The virgin will conceive… and shall call his name Immanuel.”",reflect:"Immanuel means ‘God with us.’ Jesus came to be with us forever.",q:"What does the name Immanuel mean?",pray:"Thank You Jesus for coming to be with us. You are God with us."},
{ref:"Luke 2:7",L:"S",scripture:"“She… laid him in a feeding trough, because there was no room… in the inn.”",reflect:"Baby Jesus, the King of everything, was born humbly in a stable. He came for everyone.",q:"Where did baby Jesus sleep?",pray:"Thank You Jesus for coming humbly, born in a simple stable for us."},
{ref:"Luke 2:10",L:"D",scripture:"“Don’t be afraid, for… I bring you good news of great joy.”",reflect:"The angel brought the best news ever: the Saviour is born! It’s great joy for everyone.",q:"What good news did the angel bring?",pray:"Thank You God for the good news of great joy — Jesus is here!"},
{ref:"Luke 2:11",L:"F",scripture:"“For there is born to you… a Saviour, who is Christ the Lord.”",reflect:"Jesus is the Saviour who came to rescue us and bring us close to God.",q:"Who is the Saviour born at Christmas?",pray:"Thank You God for sending Jesus, our Saviour and Lord."},
{ref:"Luke 2:13",L:"S",scripture:"“Suddenly there was… a multitude of the heavenly army praising God.”",reflect:"A huge choir of angels sang for joy when Jesus was born. Heaven celebrated!",q:"Who sang when Jesus was born?",pray:"Like the angels, God, I praise You for the birth of Jesus!"},
{ref:"Luke 2:14",L:"G",scripture:"“Glory to God in the highest, on earth peace, good will toward men.”",reflect:"The angels’ song brings glory to God and peace to everyone Jesus came to save.",q:"What did the angels sing about?",pray:"Glory to You in the highest, God! Thank You for peace through Jesus."},
{ref:"Luke 2:16",L:"T",scripture:"“They came with haste and found… the baby lying in the feeding trough.”",reflect:"The shepherds hurried to see Jesus. We can be excited to come to Him too.",q:"Who came to see baby Jesus first?",pray:"Help me come to You with joy, Jesus, like the happy shepherds."},
{ref:"John 1:14",L:"T",scripture:"“The Word became flesh, and lived among us… full of grace and truth.”",reflect:"Jesus, who was with God from the start, became a real person to live among us.",q:"Isn’t it amazing that God came to live with us?",pray:"Thank You Jesus for coming to live among us, full of love and truth."},
{ref:"Matthew 1:21",L:"Y",scripture:"“You shall name him Jesus, for it is he who shall save his people.”",reflect:"The name Jesus means ‘Saviour.’ He came to save us because He loves us.",q:"What does the name Jesus mean?",pray:"Thank You Jesus for coming to save us. Your name means Saviour."},
{ref:"John 3:17",L:"F",scripture:"“For God didn’t send his Son… to judge the world, but… to save the world.”",reflect:"Jesus didn’t come to tell us off — He came to save us because God loves us so much.",q:"Why did God send Jesus?",pray:"Thank You God for sending Jesus to save us, not because we earned it, but because You love us."},
{ref:"Isaiah 40:11",L:"H",scripture:"“He will gather the lambs in his arm… and gently lead those… with young.”",reflect:"Jesus is a gentle Shepherd who holds us close, like a lamb in loving arms.",q:"How does Jesus care for you gently?",pray:"Thank You Jesus for holding me close, like a gentle shepherd."},
{ref:"Matthew 2:2",L:"W",scripture:"“We saw his star… and have come to worship him.”",reflect:"Wise men followed a bright star to find Jesus and worship Him with gifts.",q:"What did the wise men follow to find Jesus?",pray:"Like the wise men, God, I want to seek Jesus and worship Him."},
{ref:"Matthew 2:10",L:"W",scripture:"“When they saw the star, they rejoiced with exceedingly great joy.”",reflect:"Finding Jesus filled the wise men with enormous joy. He fills us with joy too!",q:"How does knowing Jesus make you feel?",pray:"Finding You fills me with joy, Jesus! Thank You for coming."},
{ref:"Matthew 2:11",L:"T",scripture:"“They… offered to him gifts: gold, frankincense, and myrrh.”",reflect:"The wise men gave their best gifts to Jesus. We can give Him our love and hearts.",q:"What gift can you give to Jesus?",pray:"I give You my heart, Jesus, as my very best gift."},
{ref:"1 John 4:9",L:"B",scripture:"“By this God’s love was revealed… that God has sent his… Son into the world.”",reflect:"God showed us His love by sending Jesus. Christmas is a celebration of that love.",q:"How did God show us His love?",pray:"Thank You God for showing Your love by sending Jesus to us."},
{ref:"Luke 2:19",L:"M",scripture:"“Mary kept all these sayings, pondering them in her heart.”",reflect:"Mary treasured every wonderful thing about Jesus. We can treasure Him in our hearts too.",q:"What wonderful thing about Jesus will you treasure?",pray:"Help me treasure You in my heart, Jesus, like Mary did."},
{ref:"John 8:12b",L:"I",scripture:"“I am the light of the world.”",reflect:"Jesus came as a light in the darkness, showing everyone the way to God.",q:"How is Jesus like a light for us?",pray:"Thank You Jesus for being the light of the world. Shine in me."},
{ref:"Galatians 4:4",L:"W",scripture:"“When the fullness of the time came, God sent out his Son.”",reflect:"God sent Jesus at exactly the perfect time. God’s timing is always just right.",q:"Isn’t it wonderful that God’s timing is perfect?",pray:"Thank You God for sending Jesus at just the perfect time."},
{ref:"Psalm 98:4",L:"M",scripture:"“Make a joyful noise to Yahweh, all the earth! Break out and sing for joy!”",reflect:"The whole earth can celebrate God’s love with joyful singing, especially at Christmas!",q:"How can you make a joyful noise to God today?",pray:"I sing for joy to You, God! Thank You for the gift of Jesus."},
{ref:"Luke 2:20",L:"T",scripture:"“The shepherds returned, glorifying and praising God.”",reflect:"After seeing Jesus, the shepherds couldn’t stop praising God. His joy stays with us.",q:"How can you praise God for Jesus today?",pray:"I glorify and praise You, God, for the wonderful gift of Jesus."},
{ref:"John 1:16",L:"O",scripture:"“Of his fullness we all received grace upon grace.”",reflect:"Jesus gives us gift after gift of grace — kindness we don’t even have to earn.",q:"What good gifts has Jesus given you?",pray:"Thank You Jesus for giving me grace upon grace, gift after gift."},
{ref:"2 Corinthians 8:9",L:"F",scripture:"“For… though he was rich, yet for your sakes he became poor.”",reflect:"Jesus left the riches of heaven to come to us, so that we could become rich in His love.",q:"What did Jesus give up to come to us?",pray:"Thank You Jesus for giving up so much to bring me Your love."},
{ref:"Hebrews 13:8",L:"J",scripture:"“Jesus Christ is the same yesterday, today, and forever.”",reflect:"Jesus never changes. He was loving in the past, He loves us now, and He always will.",q:"Isn’t it good that Jesus never changes?",pray:"Thank You Jesus that You are always the same, loving me forever."},
{ref:"Psalm 90:1",L:"L",scripture:"“Lord, you have been our dwelling place for all generations.”",reflect:"As one year ends, we remember God has been our safe home all along, and always will be.",q:"How has God been with your family this year?",pray:"Thank You God for being our safe home all year long."},
{ref:"Lamentations 3:22",L:"I",scripture:"“It is because of Yahweh’s loving kindnesses that we are not consumed… they are new every morning.”",reflect:"God’s mercies are brand new every single morning. Tomorrow brings fresh love from Him.",q:"What is exciting about God’s love being new each morning?",pray:"Thank You God that Your love is new every morning, all year through."},
{ref:"Numbers 6:24",L:"Y",scripture:"“Yahweh bless you, and keep you… and give you peace.”",reflect:"As the year ends, we can pray God’s blessing over each other for the year ahead.",q:"What blessing would you like to pray for your family?",pray:"Bless and keep our family, God, and give us Your peace in the new year."},
{ref:"Revelation 21:5",L:"B",scripture:"“Behold, I am making all things new.”",reflect:"God loves fresh starts. A new year is a chance to grow closer to Him, hand in hand.",q:"What good thing do you hope to do with God next year?",pray:"Thank You God for new starts. Help our family grow closer to You."}
];
